/* Tomtini – Inhalte v3 (nach Durchspiel 7. Nov 2026).
   Platzhalter: {kinder} Namen · {eltern} Anrede · {ritual} Familienritual · {finale} Datum des letzten Tages · {essen} Lieblingsessen (falls eingetragen).
   Anrede-Tokens: {Mehrzahl|Einzahl}. kurz = Fassung 3–4 Jahre. ps = Nachsatz für ein älteres Geschwister, wenn kurz gilt.
   basis = das, was der Brief braucht (ehrliche Minuten, abends vorher). extra = Wochenend-Zugabe (tagsüber, mit Kind).
   Weltregeln (verbindlich): Tomte wird nie gesehen. Die Tür geht nur von innen auf, von außen ist sie nur gemalt.
   Grundregel 2: Tomte ist ein guter Wichtel. Immer. Nichts, was er tut, erschreckt, beschämt, droht oder prüft; wenn ein Satz das könnte, ist er falsch.
   Tomte ist nachts unterwegs, überall in der Wohnung außer in den Kinderzimmern, leise; morgens findet man, was er getan hat. Er ist kleiner als eine Kinderhand.
   Tagsüber bekommt er mit, was im Haus passiert (er sieht nicht zu, man erzählt es ihm), und darf unsichtbar Gutes tun. Tomte kann tragen, aber nicht hoch hinauf.
   Schrumpfen kann er nur, was ihm geschenkt wird. Er erzieht nicht: Er erzählt von sich, Mimi und Rubi, bittet nie um Verhalten, prüft nie, dankt nie unter Bedingung.
   Ein Nein des Kindes ist immer möglich und hat keine Folge. Jede Nacht baut er die Zahl des Tages auf die Zahlentafel vor seiner Tür. Im Januar wird er müde, nie schwach. */
window.TOMTINI = {
  vorabend: {
    titel: "Jemand zieht ein",
    von: "rubi",
    brief: [
      "Hallo {ihr da drinnen|du da drinnen}!",
      "Ich bin Rubi, ein Rotkehlchen. Ich fliege für jemanden, der heute Nacht hier einziehen möchte. Er ist sehr klein, sehr nett und braucht eine Wand für eine sehr kleine Tür.",
      "Er hat mich gebeten zu fragen, ob das für {euch|dich} in Ordnung ist. Wenn ja, {legt|leg} ein Blatt hin, auf dem JA steht, ich hole es heute Nacht ab. Wenn nicht oder noch nicht, ist das auch in Ordnung. Dann warte ich ein Stück weiter oben im Baum, egal wie lange. Er ist nicht beleidigt, er ist Wichtel.",
      "Die schlafende Maus auf dem Briefkasten gehört zu ihm. Nicht wecken, sie hatte einen langen Flug. Also, ich hatte den Flug. Sie hat geschlafen."
    ],
    kurz: ["Hallo {ihr da drinnen|du da drinnen}!", "Ich bin Rubi, ein Vogel. Morgen zieht hier jemand ein. Er ist sehr klein und sehr nett und braucht eine Wand für eine sehr kleine Tür.", "Wenn {ihr|du} das {wollt|willst}, {malt|mal} ihm ein JA auf ein Blatt. Dann kommt er. Wenn nicht, auch gut, dann wartet er.", "Die Maus auf dem Briefkasten schläft. Sie gehört zu ihm."],
    briefFigur: [
      "Hallo {ihr da drinnen|du da drinnen}!",
      "Ich bin Rubi, ein Rotkehlchen. Ich fliege für jemanden, der heute Nacht hier einziehen möchte, wenn {ihr|du} ja {sagt|sagst}. Er hat {euren|deinen} Wichtel vorausgeschickt, damit {ihr|du} nicht erschreckt. Der Wichtel, den {ihr|du} schon {kennt|kennst}, ist sein Bote aus Stoff. Er selbst bleibt unsichtbar, so ist das bei Wichteln.",
      "Wenn ja, {legt|leg} ein Blatt hin, auf dem JA steht, ich hole es heute Nacht ab. Wenn nicht, warte ich, ohne böse zu sein.",
      "Die schlafende Maus auf dem Briefkasten gehört auch zu ihm. Nicht wecken."
    ],
    basis: { t: "Briefkasten, Mimi, Rubis Frage", x: "Nur den Briefkasten an der Fußleiste anbringen, das Mimi-Bild darauf, den Rubi-Zettel davor. Drei Vogelspuren mit einer Gabel in einem Teelöffel Mehl auf Backpapier, mehr nicht. Rubis Zettel wird am Morgen danach gelesen, das JA kommt tagsüber, Tür und Tafel am selben Abend, der erste Tomte-Brief am Morgen darauf (bei Start 1.12.: Zettel am 30.11., Tür am Abend des 30.11.). Bei Nein oder Zögern: Rubis Warte-Zettel hinlegen, nichts montieren, in ein paar Tagen oder nächstes Jahr wieder fragen.", m: "Briefkasten, Mimi-Bild, Mehl, Backpapier, Gabel", min: 8, zeit: "zwei Abende vor Tag 1 (bei Start 1.12.: Abend des 29.11.)" },
    nein: { von: "rubi", text: "Alles gut. Dann warte ich. Mimi auch, die merkt es nicht. Wenn {ihr|du} es {euch|dir} anders {überlegt|überlegst}, {legt|leg} einfach ein JA hin, egal wann." },
    ja: { t: "Nach dem JA: Tür und Zahlentafel", x: "Am Abend nach dem JA: Tür anbringen (Klemmbaustein-Portal nach Anleitung aus dem Druckpaket, Papiervorlage oder gekaufte Tür) und daneben die Zahlentafel mit der 1 (Steinmuster aus dem Druckpaket oder Zahlenkarte). Das JA-Blatt in die Tomte-Kiste, Rubi hat es abgeholt.", m: "Tür oder Portal, Zahlentafel", min: 15, zeit: "abends nach dem JA" },
    extra: { t: "Das Portal bauen", x: "Nach dem JA bauen die Kinder tagsüber das Portal aus Klemmbausteinen (Anleitung im Druckpaket, 8 Schritte) oder bemalen die Türvorlage. Sie wissen nur: Jemand sehr Kleines braucht eine sehr kleine Tür.", m: "Klemmbausteine oder Türvorlage, Buntstifte", min: 30 },
    tipp: "Heute Abend auch die Tomte-Kiste anlegen: ein Schuhkarton, in den alles wandert, was die Kinder Tomte geben. Daraus wird am Ende das Finale. Druckt die Notfall-Briefe gleich mit und legt sie in die Kiste."
  },
  tage: [
    { n: 1, kap: 1, titel: "Die Tür ist da",
      brief: ["Hallo {ihr da|du}! Rubi sagt, {ihr heißt|du heißt} {kinderfalsch}. Das kann nicht stimmen. {Schreibt|Schreib} mir bitte {eure Namen|deinen Namen} richtig auf.", "Ich bin Tomte. Ich wohne jetzt hinter dieser Tür. Sie geht nur von innen auf, von außen ist sie nur gemalt. Also nicht wundern, wenn nichts passiert. Nachts bin ich unterwegs, dann ist es still im Haus. Drei Dinge {sollt ihr|sollst du} wissen: Ich bin kleiner als {eure|deine} Hand. In {euer|dein} Zimmer gehe ich nie, das ist {eures|deins}. Und ich mache nur Dinge, über die man lacht. Jede Nacht baue ich die Zahl des Tages auf die Tafel neben meiner Tür, damit {ihr|du} {wisst|weißt}, wie lange ich schon da bin.", "Die Maus auf dem Briefkasten ist Mimi, meine Postbotin. Wenn sie morgens schläft, {klopft|klopf} dreimal leise. Dann weiß sie, dass {ihr|du} wach {seid|bist}.", "Danke für das JA. Es hängt jetzt in meiner Stube."],
      kurz: ["Hallo {ihr da|du}! Rubi sagt, {ihr heißt|du heißt} {kinderfalsch}. Stimmt das? Ich glaube nicht. {Sagt|Sag} es Mimi laut, sie merkt es sich im Schlaf.", "Ich bin Tomte. Ich wohne hinter dieser Tür. Ich bin kleiner als {eure|deine} Hand. In {euer|dein} Zimmer gehe ich nie. Ich mache nur Sachen zum Lachen. Nachts baue ich die Zahl neben meiner Tür.", "Die Maus heißt Mimi. {Klopft|Klopf} morgens dreimal leise, dann weiß sie, dass {ihr|du} wach {seid|bist}.", "Danke für das JA."],
      zettel: { von: "rubi", text: "Ich habe {eure Namen|deinen Namen} genau so verstanden. Fast genau so." },
      basis: { t: "Fußspuren zur Tür", x: "Vier kleine Fußabdrücke (zwei Fingerspitzen) in Mehl auf einem 50 cm langen Backpapierstreifen vor der Tür. Nicht quer durch den Flur, das wird morgens zertreten.", m: "Mehl, Backpapier", min: 4, zeit: "abends vorher" },
      extra: { t: "Begrüßungsbild", x: "Die Kinder malen Tomte ein Willkommensbild. Nachts „schrumpft“ es: verkleinert drucken oder abfotografieren und klein ausdrucken, neben die Tür hängen.", m: "Papier, Stifte, Drucker", min: 20 },
      tipp: "Das Dreimal-Klopfen wird euer Morgenritual. Bei zwei Kindern: eines klopft, eines hält den Brief, täglich tauschen. Die Namen kommen in die Tomte-Kiste." },
    { n: 2, kap: 1, titel: "{Eure Namen|Dein Name}",
      brief: ["Hallo {kinder}!", "Jetzt weiß ich es: {kinder}. Rubi hatte fast alles falsch. Ich habe {euch|dir} ein Schild gemacht. Es gehört über die Tür, aber da komme ich nicht hin, die Tür ist so hoch wie ich. {Hängt ihr|Hängst du} es auf?", "Hinter meiner Tür ist es noch ziemlich leer. Was schmeckt in diesem Haus am besten? Mimi sagt Kekse. Mimi sagt das auch über Socken."],
      kurz: ["Hallo {kinder}!", "Jetzt weiß ich {eure Namen|deinen Namen}. Ich habe ein Schild gemacht. {Hängt|Häng} es bitte über meine Tür, da komme ich nicht hin.", "Was {esst ihr|isst du} am liebsten? Mimi sagt Kekse."],
      zettel: { von: "mimi", text: "Kekse. Ich bleibe dabei." },
      basis: { t: "Namensschild", x: "Namensschild aus dem Druckpaket ausschneiden und vor die Tür legen. Die Kinder kleben es morgens über die Tür. Die Antwort zum Lieblingsessen abends in den Generator eintragen, Tomte nennt es an Tag 10.", m: "Druckpaket, Schere, Klebefilm", min: 3, zeit: "abends vorher" },
      extra: { t: "Türschild selbst gemacht", x: "Ein eigenes Schild aus Pappe. Kein Salzteig, wenn ein Hund im Haus ist (giftig). Nachts hängt es „von Rubi gerade gerückt“.", m: "Pappe, Stifte", min: 20 },
      tipp: "Ohne Drucker: Schild in Druckbuchstaben mit der „anderen“ Hand schreiben, dann sieht es nicht nach euch aus." },
    { n: 3, kap: 1, titel: "Mimi ist zu grau",
      brief: ["Hallo {kinder},", "ich habe ein Problem mit Mimi. Sie ist so grau wie der Flur, und wenn sie irgendwo einschläft, finde ich sie nicht. Gestern habe ich eine Stunde gesucht. Sie lag auf dem Brief.", "{Macht ihr|Machst du} sie bunt? Schal, Mütze, was {ihr wollt|du willst}. Dann sehe ich sie von weitem.", "Sie hat gesagt, sie möchte gern ein Kissen. Das war ihr längster Satz seit Tagen."],
      kurz: ["Hallo {kinder},", "Mimi ist so grau, dass ich sie immer verliere. Gestern lag sie auf meinem Brief, und ich habe sie nicht gesehen. {Malt|Mal} sie bunt, dann finde ich sie.", "Sie wünscht sich ein Kissen, hat sie gesagt. Dann war sie wieder weg."],
      ps: "P.S. für die Großen: Mimi hat gestern 19 Stunden geschlafen. Rubi hat mitgezählt. Rubi zählt gern.",
      zettel: { von: "rubi", text: "Ich habe sie gefunden. Auf dem Brief. Mimi hat nicht mal gemerkt, dass sie gefunden wurde." },
      basis: { t: "Mimi-Ausmalbild", x: "Das Mimi-Ausmalbild aus dem Druckpaket vor die Tür legen. Ab morgen liegt die bunte Mimi auf dem Briefkasten, die graue wandert in die Kiste (Ersatz, falls die bunte verloren geht). Bei zwei Kindern wird das eine Bild gemeinsam ausgemalt.", m: "Druckpaket, Buntstifte", min: 2, zeit: "abends vorher" },
      extra: { t: "Mimis Kissen", x: "Aus einem Stoffrest oder Wattepad ein Mini-Kissen. Nachts liegt Mimi darauf, mit einem Zettel: „Danke. Weich.“", m: "Stoffrest oder Wattepad", min: 15 },
      tipp: "Ab heute liegt Mimi jeden Morgen woanders am Briefkasten (daneben, darauf, darunter). Ein Suchmoment ohne Aufwand. Sie bleibt bis Tag 20 am Briefkasten." },
    { n: 4, kap: 1, titel: "Rubi übertreibt",
      brief: ["Hallo {kinder},", "danke für die bunte Mimi. Ich habe sie heute Nacht sofort gefunden. Sie lag im Briefkasten.", "Rubi war draußen und ist ganz aufgeregt zurückgekommen. Er sagt, der Schnee liegt so hoch wie {euer|dein} Haus, und ein Hund hat ihn gejagt, der so groß war wie ein Bus. Ich glaube ihm nicht alles. Aber nachts sehe ich draußen nur Dunkel, und tagsüber bin ich in der Stube.", "{Schaut ihr|Schaust du} für mich aus dem Fenster und {malt|malst} mir, wie es draußen wirklich ist? Schnee oder kein Schnee reicht mir schon."],
      ohne: "Mimi ist noch grau, dann suche ich eben länger. Heute Nacht habe ich sie trotzdem gefunden: Sie lag im Briefkasten und hat geschnarcht.",
      kurz: ["Hallo {kinder},", "danke für die bunte Mimi. Jetzt finde ich sie.", "Rubi sagt, draußen liegt Schnee bis zum Dach, und ein Hund war so groß wie ein Bus. Ich glaube ihm nicht.", "{Schaut|Schau} aus dem Fenster und {malt|mal} mir, wie es wirklich ist."],
      zettel: { von: "rubi", text: "Der Hund war so groß wie ein Bus. Ein kleiner Bus." },
      basis: { t: "Rubis Spuren", x: "Drei Vogelspuren (Gabel) in einem Teelöffel Mehl auf Backpapier vor der Tür. Dazu eine kleine Feder, falls eine da ist, und Papier und Stifte für das Wetterbild. Das Bild kommt abends in die Kiste. Letzter Mehltag.", m: "Mehl, Gabel, Backpapier, Papier, Stifte", min: 3, zeit: "abends vorher" },
      extra: { t: "Wetterbild für Tomte", x: "Die Kinder malen ein großes Wetterbild vom Fenster aus. Nachts hängt es verkleinert an Tomtes Tür.", m: "Papier, Stifte", min: 20 },
      tipp: "Fenster bleibt verriegelt, ein Erwachsener schaut mit. Das Wetterbild kommt in die Kiste." },
    { n: 5, kap: 1, titel: "Meine Stube",
      brief: ["Hallo {kinder},", "{euer|dein} Wetterbild hängt jetzt in meiner Stube, neben dem Ofen. Rubi hat lange hingeschaut und nichts gesagt. Das ist selten.", "Meine Stube ist klein. Ofen, Schaukelstuhl, eine Tasse, die immer dampft, weil ich sie nie austrinke. Irgendetwas fehlt noch. {Malt|Mal} oder {baut|bau} mir eine Sache und {stellt|stell} sie neben die Tür. Da ist mein Vorgarten, da darf alles stehen.", "Schrumpfen kann ich übrigens nur, was mir geschenkt wird. Alles andere bleibt so groß, wie es ist."],
      ohne: "draußen sehe ich weiter nur Dunkel, und Rubi behauptet weiter, der Schnee sei so hoch wie das Haus. Ich glaube ihm immer noch nicht.",
      kurz: ["Hallo {kinder},", "{euer|dein} Bild hängt jetzt in meiner Stube. Danke.", "Ich habe einen Ofen und einen Stuhl. Was fehlt? {Malt|Mal} mir etwas und {stellt|stell} es neben die Tür. Da ist mein Garten."],
      ps: "P.S. für die Großen: Geschenke kann ich schrumpfen. Einmal hat mir Rubi einen Zapfen geschenkt und ihn dabei nicht losgelassen. Er war drei Tage sehr klein und sehr beleidigt.",
      zettel: { von: "mimi", text: "Ein Kissen. Ich sag's nur noch einmal. Ein Kissen." },
      basis: { t: "Blick in die Stube", x: "Das Bild „Tomtes Stube“ aus dem Druckpaket neben die Tür legen. Die Kinder sehen, wo er wohnt. Er selbst ist nicht im Bild. Was die Kinder bauen, bleibt neben der Tür stehen und wird nicht weggeräumt.", m: "Druckpaket", min: 2, zeit: "abends vorher" },
      extra: { t: "Möbel für Tomte", x: "Aus Bausteinen oder Streichholzschachteln ein Möbelstück bauen. Es steht ab jetzt im „Vorgarten“ neben der Tür, nachts mit einem Dankeszettel aus dem Druckpaket.", m: "Bausteine oder Schachteln", min: 30 },
      tipp: "Tomtes Vorgarten wächst bis zum Finale. Nichts davon wegräumen, auch wenn der Flur voller wird." },
    { n: 6, kap: 1, titel: "Ein besonderer Morgen", variante: "nikolaus",
      brief: ["Hallo {kinder},", "heute Nacht hat es an {eurer|deiner} Tür geraschelt: der Nikolaus, den {ihr kennt|du kennst}. Er hat etwas hingestellt und ist leise wieder gegangen. Ich habe nur seinen Mantel gesehen, von unten. Mimi hat sich so gefreut, dass sie einen Tannenzapfen versteckt hat. Aus Versehen. Sie versteckt, wenn sie aufgeregt ist.", "Jetzt finde ich ihn nicht. {Schaut ihr|Schaust du} nach, ob irgendwo ein Zapfen liegt, der nicht dahin gehört?"],
      kurz: ["Hallo {kinder},", "heute Nacht war der Nikolaus da. Mimi hat sich gefreut und einen Zapfen versteckt.", "{Findet ihr|Findest du} ihn?"],
      briefAlt: ["Hallo {kinder},", "heute Nacht ist etwas passiert, das ich noch nie erlebt habe. Der Wind hat so getobt, dass Mimi aufgewacht ist. Das passiert einmal im Jahr. Sie hat vor Aufregung einen Tannenzapfen versteckt und ist wieder eingeschlafen.", "{Schaut ihr|Schaust du} nach, ob irgendwo ein Zapfen liegt, der nicht dahin gehört? Er ist von draußen. Rubi hat ihn mitgebracht."],
      kurzAlt: ["Hallo {kinder},", "der Wind hat getobt. Mimi ist aufgewacht und hat einen Zapfen versteckt.", "{Findet ihr|Findest du} ihn?"],
      zettel: { von: "mimi", text: "Ich habe nichts versteckt. Ich habe geschlafen. Vielleicht beides." },
      basis: { t: "Der versteckte Zapfen", x: "Einen Tannenzapfen im Flur oder Wohnzimmer verstecken, nicht im Kinderzimmer. Der gefundene Zapfen kommt danach in Tomtes Vorgarten neben die Tür. Unter 5 Jahren immer Zapfen, keine Nuss. Ab 5 darf es eine Walnuss sein (ganz, nicht geöffnet; Nussallergie beachten).", m: "Tannenzapfen", min: 2, zeit: "abends vorher" },
      extra: { t: "Zapfen-Wichtel", x: "Aus dem gefundenen Zapfen mit Filz und Wolle einen kleinen Zapfenmann basteln. Er steht ab jetzt in Tomtes Vorgarten.", m: "Zapfen, Filzrest, Wolle, Kleber", min: 25 },
      tipp: "Nikolausabend ist Doppellast. Der Zapfen reicht, mehr nicht. Hund im Haus: Zapfen außer Reichweite." },
    { n: 7, kap: 1, titel: "Die erste Bitte",
      brief: ["Hallo {kinder},", "Mimi hat heute Nacht den Zapfen in meinem Vorgarten entdeckt und tut so, als hätte sie ihn gefunden. Sie ist sehr stolz.", "Ich brauche {eure|deine} Hilfe. In meiner Werkstatt baue ich an etwas, und mir sind die weichen Sachen ausgegangen. Wichtel polstern mit Hobelspänen, hier gibt es keine.", "{Legt|Leg} mir bitte drei weiche Dinge vor die Tür: eine alte Socke, ein Wattepad, einen Wollfaden oder so etwas. Nichts, was {ihr|du} zum Einschlafen {braucht|brauchst}. {Ihr bekommt|Du bekommst} alles am Ende zurück, versprochen.", "Was ich baue, verrate ich noch nicht."],
      ohne: "Mimi sucht ihren Zapfen immer noch. Sie sucht im Schlaf, das dauert. Rubi sagt, er weiß, wo er liegt, und sagt es nicht.",
      kurz: ["Hallo {kinder},", "ich baue etwas in meiner Werkstatt. Ich brauche drei weiche Sachen: eine alte Socke, ein Wattepad, einen Wollfaden.", "{Legt|Leg} sie vor die Tür. {Ihr bekommt|Du bekommst} sie am Ende zurück. Was ich baue, ist ein Geheimnis."],
      zettel: { von: "mimi", text: "Er baut was. Es hat geklopft. Ich hab's verschlafen, aber es hat geklopft." },
      basis: { t: "Die Sachen wandern in die Werkstatt", x: "Was die Kinder hinlegen, kommt in die Tomte-Kiste. Dafür liegt morgens ein kleines Holzstückchen da. Die weichen Sachen werden am Finale Mimis Bett.", m: "Kleines Holzstück", min: 2, zeit: "abends vorher" },
      extra: { t: "Blick in die Werkstatt", x: "Das Bild „Tomtes Werkstatt“ aus dem Druckpaket: Werkbank, Pläne, etwas unter einem Tuch. Die Kinder dürfen raten.", m: "Druckpaket", min: 10 },
      tipp: "Wenn ein Kind trotzdem das Kuscheltier hergibt: am selben Abend mit einem Zettel zurücklegen, „Zu wertvoll, das behältst du. Danke trotzdem.“" },
    { n: 8, kap: 2, titel: "Die Socken",
      brief: ["Hallo {kinder},", "ich wollte helfen. Vor meiner Tür lagen Socken, und Wichtel sortieren gern. Also habe ich sortiert: nach Farbe. Rubi sagt, das ist falsch, Socken gehören zu zweit. Diesmal glaube ich ihm, er hat es dreimal gesagt.", "Vier Socken liegen vor der Tür. Wenn {ihr|du} Lust {habt|hast}, {legt|leg} sie so hin, wie Menschen das machen. Dann weiß ich es fürs nächste Mal."],
      kurz: ["Hallo {kinder},", "ich habe Socken sortiert. Nach Farbe. Rubi sagt, das ist falsch. Er hat es dreimal gesagt.", "Vier Socken liegen vor der Tür. {Zeigt|Zeig} mir, wie es richtig geht."],
      zettel: { von: "rubi", text: "Dreimal. Ich habe es dreimal gesagt." },
      basis: { t: "Vier Socken", x: "Vier Socken (zwei Paare) „nach Farbe sortiert“ vor die Tür legen. Keine Sauerei, nur vier Socken. Morgens bleiben sie liegen, bis die Kinder sie gepaart haben.", m: "4 Socken", min: 1, zeit: "abends vorher" },
      extra: { t: "Sockenpuppe für Mimi", x: "Aus einer alten Socke eine kleine Puppe. Augen aufmalen statt Knöpfe, wenn Kinder unter 3 im Haus sind.", m: "Socke, Stifte, Füllwatte", min: 25 },
      tipp: "Die Socken kommen aus dem Wäschekorb, nicht aus dem Kinderzimmer. Tomte war nicht in den Zimmern, die Socken lagen „vor seiner Tür“." },
    { n: 9, kap: 2, titel: "Ich lerne",
      brief: ["Hallo {kinder},", "die Socken liegen jetzt zu zweit. Mimi hat draufgeschlafen und sagt, zu zweit ist weicher. Dann habe ich geübt: {Eure Hausschuhe standen|Deine Hausschuhe standen} vor meiner Tür, einer links, einer rechts, ganz allein. Jetzt stehen sie zusammen. Zu zweit. Richtig?", "Ich glaube, ich habe es verstanden. Rubi sagt, als Nächstes lerne ich Handschuhe. Davor habe ich ein bisschen Angst."],
      ohne: "die Socken liegen noch da, nach Farbe. Vielleicht ist das bei Menschen ja auch erlaubt. Ich habe trotzdem geübt: {Eure Hausschuhe standen|Deine Hausschuhe standen} vor meiner Tür, einer links, einer rechts, ganz allein. Jetzt stehen sie zusammen. Zu zweit. Richtig?",
      kurz: ["Hallo {kinder},", "die Socken sind jetzt zu zweit. Danke.", "Ich habe geübt: {Eure Hausschuhe stehen|Deine Hausschuhe stehen} jetzt auch zusammen. Richtig so? Rubi sagt, als Nächstes kommen Handschuhe."],
      zettel: { von: "rubi", text: "Handschuhe haben fünf Finger. Das wird dauern." },
      basis: { t: "Hausschuhe zu zweit", x: "Die Hausschuhe der Kinder nach dem Zubettgehen paarweise vor die Wichteltür stellen, Spitzen zur Tür. Nichts aus dem Bad.", m: "–", min: 1, zeit: "abends spät, wenn die Kinder schlafen" },
      extra: { t: "Werkbank für Tomte", x: "Aus Bausteinen eine kleine Werkbank für Tomtes Vorgarten bauen, mit Platz für die Sachen, die noch kommen.", m: "Bausteine", min: 25 },
      tipp: "Ein Tag, an dem Tomte etwas gelingt. Nach zwei Pannen tut das der Figur gut." },
    { n: 10, kap: 2, titel: "Das Frühstück",
      brief: ["Hallo {kinder},", "{ihr habt|du hast} mir erzählt, dass {essen} hier am besten schmeckt. Das wollte ich {euch|dir} heute Nacht zum Frühstück machen. Ich habe es versucht.", "Der Kühlschrank ist zu schwer (schrumpfen geht nicht, er ist kein Geschenk). Die Löffelschublade klemmt. Und der Toaster hat mich angeknurrt. Mimi hat auf meinem Rücken geschlafen, das hat nicht geholfen. In {euren Schalen|deiner Schale} liegt, was ich tragen konnte. Der Toaster hat gewonnen."],
      kurz: ["Hallo {kinder},", "{ihr habt|du hast} gesagt, {essen} schmeckt am besten. Das wollte ich {euch|dir} heute Nacht machen.", "Der Kühlschrank war zu schwer. Der Toaster war zu hoch. In {euren Schalen|deiner Schale} liegt, was ich tragen konnte."],
      ps: "P.S. für die Großen: Der Toaster ist dreimal so groß wie ich. Rubi hat gemessen. Mit dem Schnabel.",
      zettel: { von: "mimi", text: "Ich hab geholfen. Ich hab die Schale bewacht. Im Schlaf." },
      basis: { t: "Ein Stück Mandarine", x: "Morgens kurz vor dem Wecken ein Mandarinenstück (oder ein kleiner Keks, der einzige Süß-Tag) in die Müslischale, dazu der Zettel „Mehr ging nicht“ aus dem Druckpaket. Nicht über Nacht stehen lassen (Haustiere, Ameisen).", m: "Mandarine, Druckpaket", min: 2, zeit: "morgens" },
      extra: { t: "Kekse für Tomte", x: "Die Kinder backen tagsüber Mini-Kekse für Tomte (Rezept im Druckpaket). Drei kommen abends vor die Tür; morgens liegen Papierkrümel aus dem Druckpaket da, die echten Kekse isst die Familie abends.", m: "Rezept, Backzutaten", min: 45 },
      tipp: "Das Lieblingsessen aus Tag 2 steht automatisch im Brief, wenn ihr es eingetragen habt. Sonst schreibt Tomte „das, was ihr mir gesagt habt“." },
    { n: 11, kap: 2, titel: "Mimis Kunstwerk",
      brief: ["Hallo {kinder},", "Mimi war heute Nacht wach. Das passiert selten, und dann passiert viel. Sie hat Rubis Kreide gefunden und einen Schneemann gemalt. Auf das Fenster. Mit den Pfoten.", "Es ist kein Schneemann geworden. Es ist ein Fleck mit Ohren. Sie ist sehr stolz. {Sagt|Sag} ihr, dass {ihr|du} ihn gesehen {habt|hast}. Das reicht ihr. Dann darf er weg."],
      kurz: ["Hallo {kinder},", "Mimi hat ans Fenster gemalt. Mit den Pfoten. Sie sagt, es ist ein Schneemann.", "{Sagt|Sag} ihr, dass {ihr|du} ihn gesehen {habt|hast}. Dann darf er weg."],
      zettel: { von: "mimi", text: "Das ist ein Schneemann. Man muss nur richtig gucken." },
      basis: { t: "Zwei Kreidepfoten", x: "Mit Fensterkreide zwei winzige Pfotenabdrücke unten ans Flur- oder Wohnzimmerfenster, nicht ins Kinderzimmer, nicht ins Bad. Mit einem feuchten Tuch in einer Minute weg.", m: "Fensterkreide", min: 2, zeit: "abends vorher" },
      extra: { t: "Fensterbild", x: "Die Kinder malen tagsüber mit Fensterkreide einen richtigen Schneemann ans Fenster, „damit Mimi sieht, wie es geht“. Erwachsener dabei, Fenster verriegelt.", m: "Fensterkreide", min: 20 },
      tipp: "Keine Mehlspuren mehr an Oberflächen, Kreide ist sauberer. Wer Fensterkreide nachbestellen muss: Zahnpasta geht zur Not auch." },
    { n: 12, kap: 2, titel: "Überraschungs-Tag",
      brief: ["Hallo {kinder},", "heute ist Überraschungs-Tag. Das ist ein Wichtelbrauch: Man macht jemandem eine Freude, mit der er nicht rechnet. {Ihr dürft|Du darfst} sagen, dass sie von {euch|dir} ist, oder sie geheimnisvoll lassen, wie {ihr|du} {mögt|magst}.", "{Sucht|Such} {euch|dir} in den nächsten Tagen einen Menschen aus, den {ihr|du} {mögt|magst} und der nicht hier wohnt. Die Oma, die Nachbarin, die Erzieherin. {Malt|Mal} ihm etwas. {Eure|Deine} Großen helfen {euch|dir}.", "Ich habe heute Nacht Mimi überrascht: ein Kissen unter den Kopf geschoben. Sie hat es nicht gemerkt. Überraschungen sind trotzdem schön."],
      kurz: ["Hallo {kinder},", "heute ist Überraschungs-Tag. Jemand, den {ihr|du} {mögt|magst} und der nicht hier wohnt, bekommt ein Bild. Oma, Nachbarin, wer {euch|dir} einfällt.", "{Ihr dürft|Du darfst} sagen, dass es von {euch|dir} ist. {Müsst|Musst} aber nicht."],
      zettel: { von: "rubi", text: "Ich habe Mimi auch überrascht. Mit Lärm. Sie hat weitergeschlafen." },
      basis: { t: "Die Überraschungs-Karte", x: "Die Karte aus dem Druckpaket vor die Tür legen. Die Kinder malen sie, wenn sie mögen; abgegeben wird, wenn es passt. Kein Nachfragen durch Tomte, keine Rückmeldung nötig.", m: "Druckpaket, Stifte", min: 2, zeit: "abends vorher" },
      extra: { t: "Freude-Paket", x: "Etwas Gebackenes oder Gebasteltes für Nachbarn, Erzieherin oder Briefträger, gemeinsam übergeben. Ein Nachmittag.", m: "Nach Wahl", min: 90 },
      tipp: "Die Übergabe darf Tage später passieren oder ausfallen. Kein Geheimhaltungsauftrag: Das Kind entscheidet, ob es sagt, von wem die Überraschung ist." },
    { n: 13, kap: 2, titel: "Festlich",
      brief: ["Hallo {kinder},", "Rubi sagt, im Dezember hängen Menschen Glitzer auf. Das war sogar wahr, ich habe nachgeschaut. Also habe ich auch geschmückt. Meine ganze Girlande reicht von meiner Tür bis zum Türgriff. Dann war sie zu Ende.", "{Habt ihr|Hast du} auch geschmückt? {Malt|Mal} es mir, von unten sehe ich nur Stuhlbeine und das Unterste vom Baum."],
      kurz: ["Hallo {kinder},", "ich habe meine Tür geschmückt. Die Girlande war zu kurz. Sie reicht bis zum Türgriff.", "{Habt ihr|Hast du} auch geschmückt? {Malt|Mal} es mir."],
      ps: "P.S. für die Großen: Die Girlande hat genau 11 Zentimeter. Rubi hat gemessen. Mit dem Schnabel.",
      zettel: { von: "mimi", text: "Es raschelt. Ich kann nicht schlafen. Doch, kann ich." },
      basis: { t: "Die kurze Girlande", x: "Ein kurzes Stück Papiergirlande (oder Geschenkband) um den Türgriff der Wichteltür wickeln, bodennah, nichts frei gespannt, keine Lichterkette, keine Schnur über 20 cm lose.", m: "Papiergirlande oder Geschenkband", min: 2, zeit: "abends vorher" },
      extra: { t: "Papierkette für Tomte", x: "Papierkette basteln (Vorlage im Druckpaket, 15 Minuten). Nachts hängt sie an der Wand entlang um die Tür, mit Klebefilm befestigt.", m: "Buntes Papier, Kleber", min: 20 },
      tipp: "Die Papierkette bleibt bis zum Finale. Wer schnell ist: Die Kinder dürfen sie selbst aufhängen, Tomte „kommt ja nicht hoch“." },
    { n: 14, kap: 2, titel: "Halbzeit: Zwei Zettel",
      brief: ["Hallo {kinder},", "heute nur ein kurzer Gruß, ich bin in der Werkstatt. Mimi und Rubi streiten, was ich baue. {Hört|Hör} nicht auf die beiden. Was {glaubt ihr|glaubst du}? {Malt|Mal} es mir.", "Ich verrate nur so viel: Es raschelt."],
      kurz: ["Hallo {kinder},", "Mimi und Rubi streiten, was ich baue. Was {glaubt ihr|glaubst du}? {Malt|Mal} es mir."],
      zettelDoppel: [
        { von: "mimi", text: "Tomte baut was. Es ist weich. Ich hab mich draufgelegt. Es ist für mich." },
        { von: "rubi", text: "FALSCH. Es hat hundert Seiten. Oder zehn. Ich kann nicht zählen. Und es glitzert. Es ist für mich." }
      ],
      basis: { t: "Die Vermutung", x: "Papier und Stifte neben die Tür. Die Kinder malen, was Tomte baut. Das Bild kommt in die Kiste und am Finale in die Chronik.", m: "Papier, Stifte", min: 1, zeit: "abends vorher" },
      extra: { t: "Hörstück: Hinter der Tür", x: "Das erste Hörstück aus dem Elternbereich: Mimi und Rubi streiten hinter der Tür, Tomte flüstert dazwischen. Handy mit dunklem Bildschirm neben die Tür, leise, abends, ein Erwachsener dabei. Erst ab 5 Jahren und nicht bei Kindern, die abends ängstlich sind; standardmäßig weglassen.", m: "Handy", min: 5 },
      tipp: "Ab heute wächst die Spannung. Die Hinweise zeigen auf Seiten und Rascheln, nicht auf einen Baum." },
    { n: 15, kap: 3, titel: "Der erste Bauplan",
      brief: ["Hallo {kinder},", "{euer|dein} Bild von gestern hängt in der Werkstatt. {Ihr seid|Du bist} nah dran, mehr sage ich nicht.", "Jetzt brauche ich {euch|dich} wirklich. Was ich baue, braucht einen Platz, an dem es steht, und einen Baum daneben, damit es nicht allein ist. Ich habe den Baum gezeichnet, aber meine Hände sind zu klein, um ihn zu bauen. Hier ist mein Plan.", "{Baut|Bau} ihn und {stellt|stell} ihn in meinen Vorgarten. Da bleibt er stehen, Bäume gehören nach draußen."],
      ohne: "Mimi und Rubi raten immer noch, was ich baue. Beide liegen falsch, beide sind sicher. Mehr sage ich nicht.",
      kurz: ["Hallo {kinder},", "ich brauche einen Baum für meinen Garten. Meine Hände sind zu klein. Hier ist mein Plan.", "{Baut|Bau} ihn und {stellt|stell} ihn neben die Tür. Da bleibt er."],
      ps: "P.S. für die Großen: Der Plan hat vier Schritte. Schritt drei ist der schwerste. Da hat Rubi beim Zeichnen draufgesessen.",
      zettel: { von: "rubi", text: "Ich sitze dann oben drauf. Das ist mein Platz. Heute Nacht fliege ich kurz zum Waldrand, Zapfen holen." },
      basis: { t: "Papier-Tanne nach Plan", x: "Falt-Tanne aus dem Druckpaket (4 Schritte, Plan steht auf dem Briefblatt). Papier 120 g oder dicker, sonst steht sie nicht. Steht ab morgen im Vorgarten neben der Tür.", m: "Druckpaket, festes Papier", min: 3, zeit: "abends vorher, Falten tagsüber mit Kind 15 Min" },
      extra: { t: "Bausteine-Tanne nach Tomtes Plan", x: "Bauanleitung aus dem Druckpaket (6 Schritte, Standardsteine). Nachts hängt eine winzige Kugel daran.", m: "Klemmbausteine", min: 30 },
      tipp: "Teil 1 von 4. Alles aus Kapitel 3 bleibt neben der Tür oder wandert in die Kiste. Nichts wegräumen." },
    { n: 16, kap: 3, titel: "Rubi steckt fest",
      brief: ["Hallo {kinder},", "nur ein paar Zeilen heute. Rubi ist am Waldrand eingeschneit und kommt nicht durch. Ihm geht es gut, er sitzt in einer Tanne und schimpft. Ohne ihn habe ich keine Nachrichten von draußen.", "Ich arbeite, Mimi schläft, es ist still. {Malt ihr|Malst du} Rubi einen Weg frei? Dann findet er zurück."],
      kurz: ["Hallo {kinder},", "Rubi steckt im Schnee fest. Ihm geht es gut, er schimpft nur.", "{Malt|Mal} ihm einen Weg frei. Dann kommt er zurück."],
      zettel: { von: "mimi", text: "Ohne Rubi ist es so schön ruhig. Hoffentlich liest er das nicht." },
      basis: { t: "Rubis Weg", x: "Ausmalbild „Rubi im Schnee“ aus dem Druckpaket vor die Tür legen. Sonst nichts. Ein bewusst leichter Abend. Wer verreist ist: Dieser Tag ist der eingebaute Reisetag, Tomte bleibt zu Hause und passt auf die Tür auf (Notfall-Brief „Ihr verreist“).", m: "Druckpaket", min: 1, zeit: "abends vorher" },
      extra: null,
      tipp: "Wenn ihr hier pausieren müsst: Dieser Tag verzeiht alles." },
    { n: 17, kap: 3, titel: "Licht für die Werkstatt",
      brief: ["Hallo {kinder},", "Rubi ist zurück, dank {eurem|deinem} Weg. Er sagt, der Schnee war so hoch wie ein Berg. Diesmal glaube ich ihm fast.", "In meiner Werkstatt habe ich nur Ofenlicht. Das ist rot und zittrig, und für das Feine brauche ich helles Licht. {Baut ihr|Baust du} mir eine Laterne? {Stellt|Stell} sie abends vor die Tür, der Schein kommt durch den Spalt. {Ihr leuchtet|Du leuchtest} von außen, ich arbeite drinnen.", "Ein Licht, das nicht brennt, bitte. Wichtel und Feuer, das geht nicht gut."],
      ohne: "Rubi ist zurück. Er hat sich selbst einen Weg gescharrt, sagt er, und der Schnee war so hoch wie ein Berg. Diesmal glaube ich ihm fast.",
      kurz: ["Hallo {kinder},", "Rubi ist zurück. Danke für den Weg. Er sagt, der Schnee war ein Berg.", "In meiner Werkstatt ist es zu dunkel. {Baut|Bau} mir eine Laterne mit einem Licht, das nicht brennt. {Stellt|Stell} sie abends vor die Tür."],
      zettel: { von: "rubi", text: "Ein BERG. Ich übertreibe nie." },
      basis: { t: "Glas-Laterne", x: "Marmeladenglas mit Butterbrotpapier bekleben, LED-Teelicht hinein. Nur LED mit verschraubtem Batteriefach oder Laterne mit Deckel: Knopfzellen sind lebensgefährlich, wenn sie verschluckt werden. Unter 4 Jahren Plastikglas oder Blechdose statt Marmeladenglas; die Laterne steht trotzdem vor der Tür. Niemals eine echte Kerze, das Papier brennt. Die Kinder schalten sie jeden Abend an und morgens aus.", m: "Glas, Butterbrotpapier, LED-Teelicht (verschraubt)", min: 5, zeit: "abends vorher, Basteln tagsüber 15 Min" },
      extra: { t: "Papierlaterne nach Plan", x: "Faltlaterne aus dem Druckpaket mit Fensterausschnitten, LED innen.", m: "Druckpaket, LED-Teelicht (verschraubt)", min: 30 },
      tipp: "Teil 2 von 4. LED-Teelicht und Ersatzbatterie stehen auf der Einkaufsliste der ersten Woche, nicht erst heute." },
    { n: 18, kap: 3, titel: "Was {macht ihr|machst du} am liebsten?",
      brief: ["Hallo {kinder},", "danke für das Licht. Ich habe die ganze Nacht gearbeitet und zum ersten Mal gesehen, wo ich hinhämmere.", "Heute keine Baustelle, nur eine Frage: Was {macht ihr|machst du} im Winter am allerliebsten, wenn {ihr|du} mit Menschen zusammen {seid|bist}, die {ihr|du} {mögt|magst}, und keiner wegwill? {Malt|Mal} es mir oder {erzählt|erzähl} es Mimi, wenn sie wach ist. Ich brauche es für die Sache in der Werkstatt. Am Ende {seht ihr|siehst du}, wofür.", "Mimi hat „schlafen“ gesagt. Das macht sie aber auch allein."],
      ohne: "es war dunkel in der Werkstatt heute Nacht, aber ich kenne sie inzwischen auswendig.",
      kurz: ["Hallo {kinder},", "danke für das Licht.", "Was {macht ihr|machst du} im Winter am liebsten, mit Menschen, die {ihr|du} {mögt|magst}? {Malt|Mal} es mir. Ich brauche es für mein Geheimnis.", "Mimi sagt: schlafen. Das zählt nicht."],
      zettel: { von: "mimi", text: "Das zählt sehr wohl." },
      basis: { t: "Das Lieblings-Bild", x: "Papier und Stifte neben die Tür. Das Bild kommt in die Kiste. Die Antwort abends in den Generator eintragen, Tomte zitiert sie am Finale.", m: "Papier, Stifte", min: 1, zeit: "abends vorher" },
      extra: { t: "Das Ritual heute", x: "Macht das Lieblingsding heute wirklich, ohne Tomte dabei zu erwähnen.", m: "–", min: 60 },
      tipp: "Was die Kinder antworten, steht am Finale im Brief. Wenn ihr nichts eintragt, sagt Tomte „das, was ihr mir erzählt habt“." },
    { n: 19, kap: 3, titel: "Papier, das es nur bei {euch|dir} gibt",
      brief: ["Hallo {kinder},", "ich brauche Papier. Aber nicht irgendeins. Papier, das es nur in diesem Haus gibt, mit {euren|deinen} Händen gemacht.", "{Nehmt|Nimm} ein großes Blatt und {macht|mach} es bunt. Mit Stiften, mit Stempeln, mit allem, was Farbe hat. {Legt|Leg} es heute Abend vor die Tür. Morgen ist es weg. Wohin, verrate ich am Ende."],
      kurz: ["Hallo {kinder},", "ich brauche buntes Papier. Von {euch|dir} gemacht.", "{Legt|Leg} es heute Abend vor die Tür. Morgen ist es weg. Wohin, ist ein Geheimnis."],
      zettel: { von: "rubi", text: "Ich weiß, wohin. Ich sag's nicht. Also fast nicht." },
      basis: { t: "Buntes Packpapier", x: "Ein großes Stück Packpapier (mindestens 50 × 70 cm, aus einem Paket) und Wachsmaler neben die Tür. Kein Wasser, keine Fingerfarbe, nichts zu putzen. Abends wandert das Papier in die Kiste; es ist das Geschenkpapier für das Finale.", m: "Packpapier, Wachsmaler", min: 2, zeit: "abends vorher" },
      extra: { t: "Kartoffeldruck", x: "Kartoffelstempel (Erwachsene schneiden) und Farbe auf Wachstuch, ein Nachmittag mit Putzen. Nur, wenn ihr Lust auf Sauerei habt.", m: "Kartoffel, Messer, Farbe, Wachstuch", min: 60 },
      tipp: "Teil 3 von 4. Das Papier flach in der Kiste aufheben." },
    { n: 20, kap: 3, titel: "Wo schläft Mimi?",
      brief: ["Hallo {kinder},", "Mimi hat sich zum Schlafen verkrochen. Sie macht das, wenn Rubi dauernd „Ich weiß es!“ ruft. Dann zieht sie um.", "{Sucht ihr|Suchst du} sie? Sie liegt irgendwo im Flur, in der Küche oder im Wohnzimmer, wo es weich und warm ist. In {euer|dein} Zimmer geht sie nie, das ist {eures|deins}. {Weckt|Weck} sie nicht. {Legt|Leg} sie einfach zurück auf den Briefkasten.", "Rubi sucht auch. Er sucht laut."],
      kurz: ["Hallo {kinder},", "Mimi hat sich zum Schlafen verkrochen. Irgendwo im Flur oder in der Küche, wo es weich ist.", "{Findet ihr|Findest du} sie? Aber leise, nicht wecken."],
      ps: "P.S. für die Großen: Rubi sucht laut. Er ruft ihren Namen in jeden Schuh. Mimi schläft trotzdem.",
      zettel: { von: "rubi", text: "MIMI! MIIIMI! Sie antwortet nicht. Typisch." },
      basis: { t: "Die Mimi-Suche", x: "Die bunte Mimi vom Briefkasten nehmen (der Briefkasten ist morgens leer) und sie im Flur, in der Küche oder im Wohnzimmer an einem weichen Ort verstecken: Mützenfach, Hausschuh, Sofakissen. Nie im Bad, nie im Schlaf- oder Kinderzimmer. Gesucht wird nach Kita oder Schule, nicht um sieben.", m: "Mimi-Bild", min: 2, zeit: "abends vorher" },
      extra: { t: "Suchbild: Tomtes Werkstatt", x: "Digitale Zugabe aus dem Elternbereich: In Tomtes Werkstatt die Mütze finden, die er verlegt hat. Ein Wimmelbild auf dem Handy, zwei Minuten, abends, ein Erwachsener dabei.", m: "Handy", min: 5 },
      tipp: "Das Versteck darf leicht sein. Es geht ums Finden, nicht ums Suchen." },
    { n: 21, kap: 3, titel: "Der Stern",
      brief: ["Hallo {kinder},", "Mimi ist zurück auf dem Briefkasten, danke. Sie hat nicht gemerkt, dass sie weg war.", "Das letzte Teil: ein Stern. Er kommt auf den Baum, und darunter steht dann, was ich gebaut habe. Hier ist der Plan. {Faltet|Falte} ihn oder {bastelt|bastel} ihn, Hauptsache, er hat Zacken und ist von {euch|dir}.", "In drei Tagen {seht ihr|siehst du} alles. Es ist nicht groß. Es ist {von uns allen|von uns beiden}."],
      ohne: "Mimi liegt wieder auf dem Briefkasten. Sie ist heute Nacht ganz allein zurückgewandert, im Schlaf, sagt Rubi. Er hat zugeschaut und nicht geglaubt, was er sah.",
      kurz: ["Hallo {kinder},", "Mimi ist zurück. Danke.", "Ich brauche noch einen Stern für den Baum. Hier ist der Plan. In drei Tagen {seht ihr|siehst du} mein Geheimnis. Es ist nicht groß. Es ist {von uns allen|von uns beiden}."],
      zettel: { von: "rubi", text: "ICH WEISS ES! Ich sag nichts. Ich sag wirklich nichts. Es ist nämlich…" },
      basis: { t: "Faltstern nach Plan", x: "Faltstern aus dem Druckpaket (5 Schritte, Plan auf dem Briefblatt; unter 5 die Ausschneide-Variante). Abends wandert er in die Kiste, morgens „in die Werkstatt geholt“.", m: "Druckpaket, Papier", min: 2, zeit: "abends vorher, Falten tagsüber 15 Min" },
      extra: { t: "Bausteine-Stern nach Plan", x: "Stern aus Klemmbausteinen nach Tomtes Zeichnung.", m: "Klemmbausteine", min: 25 },
      tipp: "Teil 4 von 4. Heute Abend die Chronik drucken (Tage 1 bis 21 aus euren Einträgen, die letzten Seiten bleiben zum Selbstschreiben frei). Der Stern wird am 24. auf den Baum gesteckt." },
    { n: 22, kap: 4, titel: "Tomte wird leise",
      brief: ["Hallo {kinder},", "ich muss {euch|dir} etwas sagen. Am {finale} treffen sich alle Wichtel im Norden und zeigen, was sie in ihrer Werkstatt gebaut haben. Jeder zeigt seines, ich zeige unseres, weil {ihr|du} mitgebaut {habt|hast}. Deshalb freue ich mich. Traurig sein ist trotzdem in Ordnung, ich bin es auch ein bisschen.", "Mimi bleibt bei {euch|dir}. Sie schläft den Winter vor meiner Tür, und wer sie hat, hat ein Stück von mir.", "Wenn {ihr|du} mir etwas mitgeben {wollt|willst}, {legt|leg} es vor die Tür. Ich nehme es mit."],
      kurz: ["Hallo {kinder},", "bald muss ich in den Norden. Da zeigen alle Wichtel, was sie gebaut haben. Ich zeige unseres.", "Mimi bleibt bei {euch|dir}. Sie schläft hier den Winter, vor meiner Tür.", "{Malt|Mal} mir etwas zum Mitnehmen."],
      ps: "P.S. für die Großen: Rubi will die Tanne mitnehmen. Sie passt nicht in den Schnabel. Er übt trotzdem.",
      zettel: { von: "mimi", text: "Ich bleibe. Ich schlafe eh. Hat jemand was dagegen?" },
      basis: { t: "Abschiedsbild, abends Finale packen", x: "Am Abend vorher nur die Abschiedsvorlage aus dem Druckpaket vor die Tür legen (2 Min). Am Abend des 22. dann das Finale packen (20 Min): Chronik-Heft im Kinderpapier von Tag 19 einwickeln, die drei weichen Dinge von Tag 7 zu Mimis Bett legen (Socke als Matratze, Wattepad als Decke). Alles in die Kiste bis zum 24. Der Stern bleibt in der Kiste und kommt am 24. auf den Baum.", m: "Druckpaket, Chronik-Druck, Kinderpapier, weiche Dinge", min: 22, zeit: "2 Min abends vorher + 20 Min am Abend des 22." },
      extra: { t: "Ein Lied für Tomte", x: "Aus dem Elternbereich: Tomtes Lied hinter der Tür (40 Sekunden). Die Kinder dürfen mitsummen.", m: "Handy", min: 5 },
      tipp: "Heute ist der Packabend, nicht der 23. Dann ist Heiligabend-Vorabend frei." },
    { n: 23, kap: 4, titel: "Morgen",
      brief: ["Hallo {kinder},", "morgen früh steht etwas vor der Tür. {Euer|Dein} Baum steht daneben, {eure|deine} Laterne leuchtet, {euer|dein} Stern sitzt oben auf dem Baum. Drinnen ist etwas, das es nur einmal gibt, weil es nur uns gibt. {Euer|Dein} Bild von gestern ist schon eingepackt, es reist mit.", "Rubi übt den Weg nach Hause. Beim Frühstück fliegt er los, er sagt, er kennt den Weg jetzt. Er ist siebenmal gegen den Schrank geflogen."],
      ohne: "morgen früh steht etwas vor der Tür. {Euer|Dein} Baum steht daneben, {eure|deine} Laterne leuchtet, {euer|dein} Stern sitzt oben auf dem Baum. Drinnen ist etwas, das es nur einmal gibt, weil es nur uns gibt. Zum Mitnehmen packe ich die Erinnerung ein, die ist leichter als Papier.",
      kurz: ["Hallo {kinder},", "morgen früh steht etwas vor der Tür. {Euer|Dein} Bild von gestern reist mit mir.", "Rubi übt den Weg nach Hause. Er ist siebenmal gegen den Schrank geflogen."],
      zettel: { von: "rubi", text: "Sechsmal." },
      basis: { t: "Der Umzugskarton", x: "Der kleine Papier-Umzugskarton aus dem Druckpaket steht vor der Tür, das Abschiedsbild der Kinder liegt darin. Sonst nichts, der 24. soll ohne Aufräumen beginnen.", m: "Druckpaket", min: 2, zeit: "abends vorher" },
      extra: null,
      tipp: "Wenn ihr am 22. gepackt habt, ist heute wirklich nur der Karton. Chronik nicht erst heute drucken." },
    { n: 24, kap: 4, titel: "Das Geschenk",
      brief: ["Hallo {kinder},", "hier ist es: unsere Geschichte. {Ihr kennt|Du kennst} {eure|deine} Hälfte. Hier ist meine: was nachts passiert ist, während {ihr|du} geschlafen {habt|hast}. Mimi beim Zapfenverstecken, Rubi im Schnee, der knurrende Toaster. Dazu {eure|deine} Briefe und Bilder. Die letzten Seiten sind leer, die {schreibt ihr|schreibst du}. Eingepackt in {euer|dein} Papier, unter {eurem|deinem} Stern.", "Ich habe {euch|dich} nie gesehen. Und {ihr|du} mich nicht. Und trotzdem kennen wir uns jetzt.", "{Ihr habt|Du hast} mir erzählt, was {ihr|du} am liebsten {macht|machst}: {ritual}. Wenn es heute so weit ist, {denkt|denk} kurz an mich.", "Mimi bleibt. Sie schläft in dem Bett, das aus {euren weichen Sachen|deiner Socke und deiner Watte} geworden ist, vor meiner Tür.", "Vielleicht sehen wir uns nächstes Jahr wieder. Wichtel wissen das nie vorher. Wenn {ihr|du} {wollt|willst}, {legt|leg} im November ein JA hin, dann klopfe ich.", "{Euer|Dein} Tomte"],
      januarZusatz: "Nach dem Treffen komme ich noch einmal kurz vorbei, müde und leise, bevor ich zu meinem Ofen gehe. Mimi weiß es schon.",
      kurz: ["Hallo {kinder},", "hier ist mein Geschenk: unsere Geschichte. {Eure|Deine} Briefe und Bilder, und meine Seite dazu, was nachts passiert ist. Eingepackt in {euer|dein} Papier.", "{Ihr habt|Du hast} mir erzählt, was {ihr|du} am liebsten {macht|machst}: {ritual}. Heute ist es so weit.", "Mimi bleibt. Sie schläft in dem Bett aus {euren weichen Sachen|deiner Socke}.", "Vielleicht sehen wir uns nächstes Jahr wieder. Wenn {ihr|du} {wollt|willst}, {legt|leg} im November ein JA hin.", "{Euer|Dein} Tomte"],
      ps: "P.S. für die Großen: Rubi ist achtmal gegen den Schrank geflogen. Er sagt sechs.",
      zettel: { von: "mimi", text: "Ich schlafe jetzt lange. {Weckt|Weck} mich im November. Ich träum von {euch|dir}." },
      basis: { t: "Das Finale steht", x: "Vor der Tür: das Geschenk, der Baum mit dem Stern obendrauf, die Laterne brennt noch (Eltern lassen sie an). Mimi liegt in ihrem Bett aus den weichen Dingen vor der Tür. Umzugskarton und Abschiedsbild sind weg, auf dem Briefkasten liegt eine einzelne Feder. Die Laterne geht erst aus, wenn Tomte „weg ist“: abends oder nach dem Hörstück.", m: "Feder", min: 3, zeit: "morgens früh" },
      extra: { t: "Abschieds-Hörstück", x: "Aus dem Elternbereich: ein Flüstern „Bis nächstes Jahr“, das Licht hinter der Tür wird langsam dunkel. 30 Sekunden. Erst ab 5, nicht bei ängstlichen Kindern.", m: "Handy", min: 3 },
      tipp: "Ohne Januar-Briefe: Die Tür bleibt hängen, Mimi schläft davor; am 6. Januar Zettel aus dem Druckpaket („Ich schlafe in der Kiste weiter, versprochen“), dann kommen Tür und Mimi in die Kiste. Mit Januar-Briefen: Tomte kommt in der Silvesternacht zurück, Tür und Mimi bleiben, siehe Nachspiel. Ob Tomte nächstes Jahr wiederkommt, entscheidet ihr im November." }
  ],
  /* Streiche-Vorrat v2 (nach Durchspiel 12. Nov 2026: Kinder, Eltern, Fachpanel). Freiwillige Zugaben, nie Pflicht. Sortiert von leicht (1) bis aufwändig (4).
     Gesammelt aus Eltern- und Bastelblogs (DE, DK), gefiltert nach den Weltregeln: keine Sauerei, nichts aus den Kinderzimmern, nichts auf Kosten eines Kindes,
     nichts mit Kühlschrank (zu schwer), keine Fäden oder Wolle über Nacht. Was hoch oben passiert, war Rubi; was krümelt, war Mimi. Mimi schreibt nur sehr kurz.
     s = Stufe · min = Minuten abends inkl. Zettel schreiben · mk = Minuten morgens mit Kind · zwei = braucht zwei Abende · we = besser am Wochenende
     m = Material · x = was die Großen tun · von/z/z2 = Zettel · ab = frühester Tag · tier = Zusatz, wenn „Haustier“ angehakt ist. */
  streicheStufen: [
    { s: 1, kurz: "Sofort", t: "Bis 4 Minuten: hinstellen, Zettel dazu" },
    { s: 2, kurz: "Papier", t: "Bis 6 Minuten: nur Papier und Stift" },
    { s: 3, kurz: "Haushalt", t: "Bis 10 Minuten: mit Dingen aus der Wohnung" },
    { s: 4, kurz: "Wochenende", t: "Fürs Wochenende: mit den Kindern oder mit Vorlauf" }
  ],
  streiche: [
    /* Stufe 1 */
    { id:"kruemel", s:1, t:"Der Keksteller", min:3, m:"1 Keks, Teller", x:"Einen Keks essen, den Teller mit den Krümeln neben die Wichteltür stellen.", von:"mimi", z:"Das war ich nicht. Ich habe geschlafen. Mit vollem Mund.", tier:"Teller erst morgens hinstellen." },
    { id:"fernbedienung", s:1, t:"Die Fernbedienung schläft", min:3, m:"Hausschuh, Taschentuch", x:"Die Fernbedienung in einen Hausschuh legen, ein Taschentuch als Decke darüber, den Hausschuh neben die Wichteltür.", von:"tomte", z:"Sie ist vom Sofa gerutscht und lag ganz allein unten. Jetzt hat sie ein Bett. Sie schläft noch.", tier:"Hausschuh aufs Regal stellen, wegen der Batterien." },
    { id:"rahmen", s:1, t:"Bilder zur Wand", min:3, m:"–", x:"Zwei, drei standfeste Bilderrahmen im Wohnzimmer oder Flur zur Wand drehen. Keine Bilder von Menschen, die fehlen.", von:"rubi", z:"Ich wollte wissen, wie Bilder von hinten aussehen. Braun. Alle. Ich habe hundert geprüft. Oder drei." },
    { id:"bananen", s:1, t:"Die Bananen gucken", min:3, m:"Bananen, Kugelschreiber", x:"Mit dem Kuli Gesichter auf die Bananen in der Obstschale malen.", von:"rubi", z:"Ich habe sie verschönert. Eine sieht aus wie ich." },
    { id:"mandarinen", s:1, t:"Mandarinen auf den Schuhen", min:3, m:"1 Mandarine pro Kind", x:"Auf ein Schuhpaar pro Kind eine Mandarine legen, obendrauf und sichtbar, nicht hinein.", von:"rubi", z:"Ich habe sie alle hergetragen. Gut, gerollt. Aber weit." },
    { id:"fundbuero", s:1, t:"Fundbüro", min:4, m:"–", x:"Drei Dinge, die herumlagen (Socke, Bauklotz, Buntstift), in einer Reihe neben die Wichteltür legen. Kind unter 3 im Haus: nichts, was durch eine Klopapierrolle passt.", von:"tomte", z:"Gefunden unter dem Sofa. Sie wollten nach Hause. Die Socke sagt nicht, wohin." },
    { id:"schuhreihe", s:1, t:"Die Schuhreihe", min:4, m:"–", x:"Die Schuhe, die im Flur herumstehen (höchstens acht Paar), der Größe nach an der Wand aufreihen.", von:"tomte", z:"Der Größe nach. Der kleinste ist ein gutes Bett. Ich habe es ausprobiert." },
    { id:"buecher", s:1, t:"Bücher verkehrt herum", min:4, m:"–", x:"Zehn Bücher im untersten Regalbrett im Wohnzimmer oder Flur mit dem Rücken nach hinten stellen.", von:"tomte", z:"Von hinten sehen alle gleich aus. Jetzt ist jedes Buch eine Überraschung." },
    { id:"loeffelstern", s:1, t:"Der Löffelstern", min:4, m:"6 Löffel", x:"Sechs Löffel als Stern neben die Wichteltür legen, dicht an die Wand.", von:"tomte", z:"Rubi hat sie aus der Schublade geschubst. Ich habe sie getragen, einer ist doppelt so lang wie ich. Es soll ein Stern sein." },
    { id:"klinken", s:1, t:"Socken auf den Klinken", min:4, m:"saubere Einzelsocken", x:"Über die Klinken im Flur je eine Socke ziehen. Nicht an Bad, Wohnungstür und Kinderzimmern.", von:"rubi", z:"Den Klinken war kalt. Ich habe hundert Socken aufgehängt. Oder vier." },
    { id:"kissenburg", s:1, t:"Die Kissenburg", min:4, we:true, m:"Sofakissen, Papier-Mimi", x:"Die Sofakissen auf dem Boden zu einer kleinen Burg zusammenstellen und die Papier-Mimi hineinlegen. Es wird getobt, deshalb besser am Wochenende.", von:"tomte", z:"Rubi hat die Kissen heruntergeschubst. Ich habe eine Burg gebaut. Mimi wohnt schon drin. Sie weiß es noch nicht." },
    /* Stufe 2 */
    { id:"wetter", s:2, t:"Rubis Wetterbericht", min:3, m:"Zettel, Stift", x:"Den Zettel neben die Wichteltür legen. Passt am Abend vor „Es hat geschneit“.", von:"rubi", z:"Wetter für heute: Schnee bis zum Dach. Mindestens. Oder gar keiner. Ich habe nur ganz kurz rausgeguckt." },
    { id:"toaster", s:2, t:"Der Toaster hat einen Namen", min:3, m:"Zettel, Stift, Klebefilm", ab:11, x:"Den Zettel neben dem Toaster an die Wand oder den Schrank kleben, nie ans Gerät. Passt erst nach Tag 10, dort knurrt der Toaster.", von:"tomte", z:"Er heißt jetzt Brummer. Wir haben uns vertragen. Rubi hat das Schild daneben aufgehängt, ich komme da nicht hoch." },
    { id:"papierschnee", s:2, t:"Es hat geschneit", min:4, m:"weißes Papier", x:"Aus weißem Papier zehn kleine Flocken reißen und nur direkt vor der Wichteltür verteilen.", von:"tomte", z:"Es hat geschneit. Nur hier. Ich habe nachgeholfen." },
    { id:"lesezeichen", s:2, t:"Tomte hat mitgelesen", min:4, m:"Papierstreifen, Zettel", x:"Nur wenn abends ein Buch im Wohnzimmer liegt: einen Papierstreifen irgendwo in die Mitte legen, auf eine Seite mit einem wirklich langen Wort. Das echte Lesezeichen bleibt, wo es ist.", von:"tomte", z:"Ich habe weitergelesen. Bis hier. Dann kam ein sehr langes Wort." },
    { id:"speisekarte", s:2, t:"Speisekarte", min:4, m:"Zettel, Stift", x:"Die Karte gefaltet neben die Wichteltür stellen.", von:"tomte", z:"Heute bei mir: Krümelsuppe. Schneeflockentee. Zum Nachtisch ein halbes Rosinchen." },
    { id:"steckbrief", s:2, t:"Mimis Steckbrief", min:4, m:"Zettel, Stift", x:"An Mimis Briefkasten neben der Wichteltür lehnen. Das letzte Wort läuft in einem Strich nach unten aus. Beim Vorlesen an der Stelle einschlafen.", von:"mimi", z:"Name: Mimi. Kann gut: schlafen. Kann nicht so gut: wach bl" },
    { id:"parkausweis", s:2, t:"Parkausweis", min:4, m:"Zettel, Stift, 1 Spielzeugauto", x:"Nur wenn abends ein Spielzeugauto im Wohnzimmer liegt: neben die Wichteltür stellen, den Zettel unter den Reifen.", von:"tomte", z:"Hier darfst du parken. Für immer. Das Auto ist größer als ich, es darf trotzdem." },
    { id:"hausordnung", s:2, t:"Hausordnung für Wichtel", min:5, m:"Zettel, Stift, Klebefilm", x:"Den Zettel neben die Wichteltür kleben.", von:"tomte", z:"Hausordnung für Wichtel. 1. Die Tür geht nur von innen auf. 2. Mimi darf überall schlafen. 3. Rubi darf alles sagen. Man muss nicht alles glauben." },
    { id:"wegweiser", s:2, t:"Der Wegweiser", min:5, m:"Papier, Stift, Klebefilm", x:"Drei Papierpfeile mit den drei Zeilen beschriften und neben der Wichteltür an die Fußleiste kleben.", von:"tomte", z:"Nordpol: weit. Küche: die halbe Nacht. Keksdose: zu hoch." },
    { id:"waesche", s:2, t:"Waschtag", min:6, m:"Papierstreifen, Buntstifte in Rot und Rosa, Klebefilm", x:"Auf einen Papierstreifen eine Wäscheleine mit winziger Wäsche malen: die Mütze rot, Hemd und Socken rosa. Neben der Wichteltür an die Fußleiste kleben.", von:"tomte", z:"Waschtag. Die rote Mütze hat abgefärbt. Jetzt ist alles ein bisschen Mütze." },
    /* Stufe 3 */
    { id:"geschmolzen", s:3, t:"Der geschmolzene Schneemann", min:5, m:"Teller, Tablett, Wasser, Möhrenspitze, 2 Pfefferkörner oder Papierpunkte", x:"Einen Teller mit einer flachen Pfütze auf ein Tablett neben die Wichteltür, darin die Möhrenspitze und zwei Punkte als Augen. Passt am Abend vor „Schneemann für drinnen“.", von:"rubi", z:"Mein Schneemann. Von draußen mitgebracht. Er war größer. Viel größer.", tier:"Tablett erhöht stellen." },
    { id:"schleife", s:3, t:"Die Schleife", min:5, m:"Klopapier, 1 Kuscheltier", x:"Tagsüber ein Kuscheltier im Wohnzimmer liegen lassen, nie das Schlaftier. Abends eine Schleife aus Klopapier um den Bauch binden und es auf ein Kissen neben die Wichteltür setzen.", von:"tomte", z:"Er wollte auch einmal schick sein. Die Schleife ist von mir. Rubi sagt, es ist ein Knoten." },
    { id:"klorollen", s:3, t:"Schneemann für drinnen", min:6, m:"3 volle Klopapierrollen, Schal oder Socke, Papier, Stift, Klebefilm", x:"Drei volle Rollen an der Wand stapeln, Schal um die Mitte, ein Gesicht aus Papier ankleben.", von:"tomte", z:"Drinnen schmilzt er nicht. Ich habe gerollt, Rubi hat gestapelt. Rubi sagt, es war andersherum." },
    { id:"teebeutel", s:3, t:"Teebeutel am Baum", min:6, m:"Früchte- oder Kräuterteebeutel ohne Klammer", x:"An die unteren Zweige vom Baum oder an eine Zimmerpflanze Teebeutel hängen, Schildchen nach vorn.", von:"rubi", z:"Kugeln sind schwer. Die hier duften. Ich habe sie nach Geruch sortiert." },
    { id:"stau", s:3, t:"Stau vor der Tür", min:6, m:"Spielzeugautos, sonst Handschuhe oder Gewürzdosen", x:"Nur mit Autos, die abends im Wohnzimmer liegen, ab drei gilt es: in einer Schlange an der Fußleiste entlang aufreihen, das erste direkt vor der Wichteltür. Ohne Autos stehen Handschuhe oder Gewürzdosen an.", von:"tomte", z:"Alle wollten gleichzeitig zu mir. Ich habe gepfiffen und gewunken. Es hat nicht geholfen." },
    { id:"badetag", s:3, t:"Badetag", min:7, m:"Schüssel, Watte, Waschlappen, 2 Kuscheltiere", x:"Tagsüber zwei Kuscheltiere im Wohnzimmer liegen lassen, von jedem Kind eins, nie das Schlaftier. Abends in eine Schüssel voll Watte setzen, ein Waschlappen über den Rand.", von:"tomte", z:"Badetag. Trocken. Mimi mag kein Wasser." },
    { id:"zeltlager", s:3, t:"Zeltlager", min:7, m:"großes Buch, Geschirrtuch, 2 Kuscheltiere, Papier-Mimi", x:"Ein großes Buch aufgeklappt wie ein Dach aufstellen, das Geschirrtuch darüber. Darunter zwei Kuscheltiere aus dem Wohnzimmer (nie das Schlaftier) und die Papier-Mimi.", von:"tomte", z:"Zeltlager. Einer schnarcht. Es ist Mimi." },
    { id:"kino", s:3, t:"Kinoabend", min:7, m:"Bilderbuch aus dem Wohnzimmer, 2 Kuscheltiere, Schälchen, ein paar Cornflakes", x:"Das Bilderbuch aufgeschlagen aufstellen, die Kuscheltiere davor (nie das Schlaftier), ein Schälchen dazu. Kind unter 4 im Haus: Schälchen erst morgens füllen.", von:"tomte", z:"Der Film war ein Buch. Wir haben die Bilder geguckt. Mimi kennt das Ende nicht.", tier:"Schälchen erst morgens füllen." },
    { id:"inventar", s:3, t:"Tomte hat gezählt", min:7, we:true, m:"Zettel, Stift", x:"Nur in Flur, Küche und Wohnzimmer zählen, kleine Mengen. Die Zahlen in die Lücken eintragen, bei den Schuhen eine zu wenig. Die Kinder zählen nach und ertappen ihn.", von:"tomte", z:"Gezählt heute Nacht, ohne Kinderzimmer, da gehe ich nicht hin: __ Türen, __ Stühle, __ Schuhe im Flur. Und 1 Mimi. Bei den Schuhen bin ich nicht sicher, einer lief weg." },
    /* Stufe 4 */
    { id:"rosinen", s:4, t:"Tanzende Rosinen", min:2, mk:10, we:true, m:"Glas, frisch geöffneter, stark sprudelnder Sprudel, kleine Rosinen", x:"Abends nur Zettel und leeres Glas hinstellen. Morgens zusammen: Sprudel einfüllen, die Kinder werfen Rosinen hinein, eine Minute Geduld. Vorher einmal allein testen.", von:"tomte", z:"Wer mag, wirft Rosinen ins Sprudelwasser. Mimi sagt, manchmal tanzen sie. Mimi hat das geträumt. Vielleicht stimmt es.", tier:"Rosinen sind für Hunde giftig. Erst morgens herausgeben, nichts fallen lassen." },
    { id:"nordlicht", s:4, t:"Nordlicht im Teller", min:2, mk:15, we:true, m:"Tablett, je Kind 1 Teller und 1 Wattestäbchen, Milch, Spülmittel, Lebensmittelfarbe (nur, wenn sie im Haus ist)", x:"Abends nur Zettel und leere Teller. Morgens mit einem Großen auf dem Tablett: Milch einfüllen, ein paar Tropfen Farbe darauf, Wattestäbchen in Spülmittel tauchen und in die Mitte tupfen. Danach sofort wegschütten. Die Farbe fleckt.", von:"rubi", z:"Nordlicht ist bunter Himmel. So sieht es aus. Ich war da. Fast. Nur gucken, nicht trinken, es schmeckt nach Spüli." },
    { id:"samen", s:4, t:"Wichtelsamen", min:4, zwei:true, m:"Glas, Zucker, Zuckerstreusel, je Kind 1 Mandarine", x:"Abend 1: ein Glas mit drei Zentimetern Zucker und ein paar Zuckerstreusel als Samen auf die Kommode, Zettel dazu. Tagsüber stecken die Kinder die Samen in den Zucker. Abend 2: Samen herausnehmen, je Kind eine Mandarine obenauf legen. Wenn es bei euch Süßes gibt: gleiche Lutscher in den Zucker stecken.", von:"tomte", z:"Wichtelsamen. In Zucker stecken, eine Nacht warten. Ich verspreche nichts. Bei mir wächst meistens Moos.", z2:"Es hat geklappt. Ich bin selbst überrascht. Rubi sagt, er wusste es." },
    { id:"ueberraschung", s:4, t:"Tomte überraschen", min:3, zwei:true, m:"Was die Kinder aussuchen", x:"Abend 1: der erste Zettel. Den Kindern sagen: Was Tomte bekommt, nimmt er mit, ein Bild ist ideal, kein Lieblingsstück. Abend 2: das Geschenk in die Tomte-Kiste legen und den zweiten Zettel hinlegen. Liegt nichts da, entfällt der zweite Zettel ohne Kommentar.", von:"tomte", z:"Mich hat noch nie jemand überrascht. Wer mag, darf es versuchen. Ich schaue nicht hin. Ich schaue nie hin.", z2:"Ich habe mich so laut gefreut, dass Mimi fast aufgewacht ist. Es steht jetzt in meiner Stube." },
    { id:"schatzkarte", s:4, t:"Mimis Schatzkarte", min:12, we:true, m:"Papier, Stifte in zwei Farben, je Kind eine gleiche Kleinigkeit aus dem Haus", x:"Je Kind eine gleiche Kleinigkeit (zwei Mandarinen, zwei Kekse in einer Dose) im Wohnzimmer verstecken, erhöht, nichts Verschluckbares. Nur diesen Raum aufzeichnen, mit drei Möbeln und je Kind einem X in eigener Farbe.", von:"mimi", z:"Ich habe etwas versteckt. Für jeden eins. Wo, weiß ich nicht mehr. Rubi hat mitgezeichnet." },
    { id:"geheimtinte", s:4, t:"Geheimtinte", min:6, mk:10, we:true, m:"Papier, Zitronensaft, Wattestäbchen, Bügeleisen, Backpapier", x:"Abends mit Zitronensaft dick einen Stern aufs Papier malen, ein Blatt pro Kind, trocknen lassen, an einem Probestück testen. Morgens bügelt ein Großer das Blatt ohne Dampf durch Backpapier, bis der Stern braun wird. Ein Föhn reicht meist nicht. Keine Kerze.", von:"tomte", z:"Auf dem anderen Blatt steht etwas. Man sieht es erst, wenn ein Großer es warm macht. Nur mit einem Großen. Es riecht nach Zitrone. Ich weiß auch nicht, warum." },
    { id:"wichtelschrift", s:4, t:"Wichtelschrift", min:15, mk:15, we:true, m:"Papier, Stift", x:"Ab etwa 6 Jahren. Einen Satz aus höchstens drei Wörtern wählen, etwa „Mimi schläft“. Nur für dessen Buchstaben je ein Zeichen erfinden (Stern, Tanne, Punkt). Den Schlüssel auf ein Blatt, den Satz in Zeichen auf ein zweites. Kleinere Geschwister zählen die Sterne.", von:"tomte", z:"Wichtelschrift. Der Schlüssel liegt daneben. Rubi kann sie nicht lesen, sagt aber ja." },
    { id:"murmelbahn", s:4, t:"Die Nussbahn", min:35, we:true, m:"4–5 leere Papprollen (ab Tag 1 sammeln), Schere, Malerkrepp, Schälchen, Papierkugel oder Wattebällchen", x:"Die Papprollen längs halbieren und als Rinnen schräg untereinander mit Malerkrepp an eine Tür oder an Fliesen kleben, unten ein Schälchen. Einmal testen. Murmel oder Haselnuss nur, wenn kein Kind unter 5 im Haus ist und niemand eine Nussallergie hat.", von:"tomte", z:"Für Nüsse gebaut. Rubi hat oben geklebt, ich unten. Mimi hat sie getestet. Sie hat nicht durchgepasst." }
  ],
  notfall: [
    { id: "vergessen1", titel: "Eine Nacht vergessen", von: "tomte",
      morgen: "Für den Morgen, ohne Brief: „Mimi hat verschlafen. Morgen früh kommt die Post doppelt, hat Rubi gesagt.“ Am nächsten Morgen liegen dann dieser Zettel, der vergessene Brief und der neue Brief zusammen da.",
      brief: ["Hallo {kinder},", "Mimi ist gestern auf dem Weg zu {euch|dir} eingeschlafen. Mit meinem Brief unter dem Arm, zusammengerollt hinter dem Schuhregal. Ich habe sie erst heute gefunden, sie hat geschnarcht.", "Hier ist der Brief. Er ist einen Tag älter, aber er stimmt noch. Nichts geht verloren, es kommt nur später.", "Haselmäuse schlafen im Winter, auch mitten im Auftrag. Ich habe ihr ein Kissen untergeschoben und den Brief vorsichtig herausgezogen."],
      kurz: ["Hallo {kinder},", "Mimi ist mit meinem Brief eingeschlafen. Hier ist er. Ein bisschen spät.", "{Seid|Sei} nicht böse. Sie ist eine Maus."],
      tipp: "Der Kalender wird nicht verschoben: Tag = Datum. Der ausgefallene Brief kommt mit diesem Zettel am nächsten Morgen dazu. Wenn der ausgefallene Tag eine Requisite brauchte, die nicht mehr passt, Requisite weglassen; die Briefe der Tage 4, 5, 9, 12, 14, 16 und 18 funktionieren auch ohne. Die Bauteile (15, 17, 19, 21) immer nachliefern." },
    { id: "vergessen2", titel: "Mehrere Nächte vergessen", von: "rubi",
      brief: ["{kinder}!", "Entschuldigung, Entschuldigung! Mimi war weg, und ich habe sie überall gesucht, zwei Tage lang. Sie lag auf dem Briefstapel und hat geschlafen. Auf den Briefen! Deshalb kam keine Post.", "Hier ist, was sich darunter angesammelt hat. Tomte sagt, er hat in der Zeit nur gebaut und nichts angestellt. {Lasst euch|Lass dir} Zeit beim Lesen.", "Mimi sagt, sie hat nichts gemerkt. Das glaube ich ihr sogar."],
      kurz: ["{kinder}!", "Mimi hat auf den Briefen geschlafen. Zwei Tage! Hier sind sie alle auf einmal. Tomte hat in der Zeit nur gebaut.", "Mimi sagt, sie hat nichts gemerkt."],
      tipp: "Nicht verschieben, nicht alles nachholen. Briefe ohne Requisite (4, 5, 9, 12, 14, 16, 18) nachliefern, die Bauteile (15, 17, 19, 21) immer, auch mit Requisite. Alles andere entfällt, Tomte „hat nur gebaut“." },
    { id: "reise", titel: "Ihr verreist (Tomte bleibt zu Hause)", von: "tomte",
      brief: ["Hallo {kinder},", "{ihr fahrt|du fährst} weg? Gute Reise. Ich bleibe hier und passe auf die Tür auf, Mimi passt auf mich auf, schlafend. Wichtel reisen nicht gern, wir werden in Taschen seekrank.", "Rubi fliegt {euch|dir} nach, wenn das Wetter mitmacht, und lässt irgendwo eine Feder liegen. Wenn {ihr|du} eine {findet|findest}, war er da. Wenn nicht, war Nebel.", "Wenn {ihr|du} zurück {seid|bist}, liegt wieder Post da. Die Zahl baue ich hier weiter, damit {ihr|du} {seht|siehst}, wie lange {ihr|du} weg {wart|warst}."],
      kurz: ["Hallo {kinder},", "{ihr fahrt|du fährst} weg? Ich bleibe hier und passe auf die Tür auf.", "Rubi fliegt {euch|dir} nach und verliert eine Feder. Wenn {ihr|du} zurück {seid|bist}, liegt wieder Post da."],
      tipp: "Diesen Brief am Abend vor der Abfahrt legen. Unterwegs ist nichts Pflicht; wer mag, legt einmal eine Feder (Druckpaket) hin. Die Tage unterwegs entfallen; zu Hause geht es mit dem Datum weiter, die Zahlentafel zeigt den aktuellen Tag. Wenn Tag 15, 17, 19 oder 21 betroffen sind, diesen einen Bauplan am ersten Abend zu Hause nachholen. Bei zwei Zuhause: Tomte wohnt in einer Wand, Rubi bringt Post ins andere Haus." },
    { id: "krank", einzeln: true, titel: "Ein Kind ist krank", von: "tomte",
      brief: ["Hallo {kinder},", "Rubi hat mir erzählt, dass es dir nicht gut geht. Dann ist heute kein Tag für Pläne. Heute ist ein Tag für Decken und Tee.", "Mimi und Rubi haben {euch|dir} ein Bild gemacht. Mimi hat dabei geschlafen, aber sie wollte es trotzdem.", "Ich bin da, hinter der Tür. {Ihr müsst|Du musst} nichts tun. {Werdet|Werd} gesund."],
      kurz: ["Hallo {kinder},", "Rubi sagt, du bist krank. Heute gibt es keine Aufgabe. Nur Ruhe.", "Mimi und Rubi haben {euch|dir} ein Bild gemalt. {Werdet|Werd} gesund."],
      tipp: "Keine Aufgabe, keine Zugabe. Das Gute-Besserung-Bild aus dem Druckpaket dazu, auf das Frühstückstablett, nicht ins Zimmer (Rubi „hat es durchs Fenster gereicht“). Der Plan läuft mit dem Datum weiter; was ausfällt, fällt aus, nur die Bauteile (15, 17, 19, 21) am ersten gesunden Abend nachholen." },
    { id: "pause", titel: "Ihr braucht eine Pause", von: "tomte",
      brief: ["Hallo {kinder},", "heute ist Wichtel-Ruhetag. Einmal im Dezember schlafen alle Wichtel einen ganzen Tag, sonst schaffen sie den Rest nicht. Heute ist dieser Tag.", "Ich schlafe. Mimi schläft sowieso. Rubi tut so.", "Morgen geht es weiter. {Schlaft|Schlaf} auch gut."],
      kurz: ["Hallo {kinder},", "heute ist Wichtel-Ruhetag. Alle Wichtel schlafen. Ich auch.", "Morgen geht es weiter."],
      tipp: "Ein legitimer Tag ohne alles. Kein Kind merkt einen Bruch." },
    { id: "tuer", titel: "Die Tür wurde geöffnet", von: "tomte",
      brief: ["Hallo {kinder},", "heute Nacht stand meine Tür offen, als ich heimkam. Das macht nichts. Menschen sehen da immer nur die Wand, das ist der Trick meiner Tür, so bleibt mein Gang geheim.", "Neugierig sein gehört zu Kindern wie Schlafen zu Mimi. Ich bin nicht böse, ich kann gar nicht böse. {Schaut|Schau} ruhig öfter, die Wand bleibt eine Wand.", "Von innen geht sie auf. Von außen bleibt sie gemalt. Das ist bei allen Wichteltüren so, auch bei offenen."],
      kurz: ["Hallo {kinder},", "Meine Tür war heute offen. Das macht nichts. Menschen sehen da immer nur die Wand. Das ist der Trick.", "Mir geht es gut. Mimi schläft. Morgen kommt wieder Post."],
      tipp: "Keine Strafe, keine Drohung, kein Verlust. Wer mag, klebt das Tunnelbild aus dem Druckpaket hinter die Tür, dann sieht das Kind beim nächsten Mal einen Gang statt der Wand." },
    { id: "erwischt", titel: "Ein Kind hat die Großen beim Hinlegen gesehen", von: "tomte", einzeln: true,
      brief: ["Hallo {kinder},", "{ihr habt|du hast} gesehen, wie mein Brief von {eltern} hingelegt wurde. Das stimmt. Meine Briefe kommen über {eltern} zu {euch|dir}, meine Hände sind zu klein für Menschenbriefe, und Mimi schläft.", "Wenn {ihr|du} etwas wissen {wollt|willst}, {fragt|frag} {eure|deine} Großen. Sie sagen {euch|dir} die Wahrheit, immer. Ich bin Wichtel, wir sind nie böse, auch nicht über Fragen.", "Und wenn {ihr|du} weiter mitspielen {wollt|willst}, freue ich mich. Wenn nicht, auch gut. Mimi schläft so oder so."],
      kurz: ["Hallo {kinder},", "{ihr habt|du hast} gesehen, wie mein Brief von {eltern} hingelegt wurde. Ja, so kommt meine Post zu {euch|dir}.", "Wenn {ihr|du} etwas wissen {wollt|willst}, {fragt|frag} {eure|deine} Großen. Sie sagen die Wahrheit."],
      elternskript: "Wenn das Kind direkt fragt „Bist du das?“: nicht leugnen, nicht umdeuten. Außerhalb der Geschichte antworten, zum Beispiel: „Ja, ich lege die Briefe hin. Tomte ist ein Spiel, das ich für dich spiele, weil ich dich mag. Willst du weiter mitspielen, mitmachen oder aufhören? Alles drei ist in Ordnung.“ Erst nachfragen, was das Kind genau wissen will, dann nur das beantworten. Wenn es nur gesehen hat und nicht fragt, reicht dieser Brief.",
      tipp: "Nur an dieses eine Kind, nicht laut vor Geschwistern vorlesen. Kein zweites Geheimnis, kein Auftrag, keine Belohnung. Ein Kind, das mitmachen möchte, darf Briefe mit hinlegen; das ist ein Angebot, keine Pflicht. Enttäuschung ist erlaubt und wird nicht weggeredet." },
    { id: "geschwister", titel: "Das ältere Kind weiß Bescheid", von: "eltern", einzeln: true,
      brief: ["Hallo {kinder},", "du weißt es jetzt. Vielleicht bist du enttäuscht oder sauer, dass du es nicht früher wusstest. Das darfst du sein, und du darfst es deinen Großen sagen.", "Du musst nichts geheim halten und auf niemanden aufpassen. Wenn du Lust hast, kannst du mitbauen: Briefe hinlegen, die Zahl bauen, beim Baum helfen. Wenn nicht, ist das genauso gut. Die Geschichte gehört dir trotzdem, du hast sie von Anfang an mitgespielt.", "Deine Großen, die Tomte spielen"],
      kurz: ["Hallo {kinder},", "du weißt es jetzt. Enttäuscht sein ist okay.", "Du musst nichts geheim halten. Mitbauen darfst du, musst du aber nicht."],
      elternskript: "Zuerst ohne Brief sprechen, außerhalb der Geschichte: „Ja, wir machen Tomte für euch. Du hast es herausgefunden. Wie geht es dir damit?“ Zuhören. Dann anbieten, nicht auftragen: mitbauen, zuschauen oder raushalten. Das jüngere Kind erfährt nichts durch diesen Brief: Er wird dem älteren Kind einzeln gegeben.",
      tipp: "Nur an das wissende Kind, nicht vor dem jüngeren. Keine Helfer-Belohnung, keine Hüter-Rolle. Wenn das ältere Kind das jüngere aufklären will, ist das seine Entscheidung; die Großen begleiten dann beide." },
    { id: "angst", titel: "Ein Kind hat Angst", von: "tomte",
      brief: ["Hallo {kinder},", "{eure|deine} Großen haben mir gesagt, dass es {euch|dir} ein bisschen unheimlich ist, dass jemand im Haus wohnt, den man nicht sieht. Das verstehe ich. Ich wäre auch vorsichtig.", "Deshalb verspreche ich {euch|dir} drei Dinge: In {euer|dein} Zimmer gehe ich nie, auch Mimi und Rubi nicht. Ich mache nur Dinge, über die man lacht, nie welche, die erschrecken. Und ich gehe sofort, wenn {ihr|du} das {wollt|willst}. {Sagt|Sag} es einfach {euren|deinen} Großen, die sagen es mir.", "Ich bin nur ein kleiner Wichtel, der Briefe schreibt."],
      kurz: ["Hallo {kinder},", "ich komme nie in {euer|dein} Zimmer. Ich mache nur Sachen zum Lachen. Und ich gehe, wenn {ihr|du} das {wollt|willst}.", "Ich bin nur ein kleiner Wichtel, der Briefe schreibt."],
      einzeln: true,
      elternskript: "Vor dem Brief, außerhalb der Geschichte: „Tomte ist ein Spiel, das wir für dich machen. Wenn du es nicht magst, hören wir sofort auf, und niemand ist traurig.“ Erst wenn das Kind weiterspielen möchte, diesen Brief geben. Beruhigung darf nicht nur von der Figur kommen, die Angst macht.",
      auszug: { von: "tomte", text: "Ich ziehe heute aus, so wie {ihr|du} es {wollt|willst}. Das ist völlig in Ordnung, Wichtel ziehen oft um. Die Tür nehme ich mit, Mimi auch. Danke, dass ich kurz da sein durfte. Tomte" },
      tipp: "Ab jetzt „leiser Tomte“: nur Briefe, Spuren nur direkt an der Tür, keine Hörstücke, Tür notfalls weiter weg vom Kinderzimmer. Wenn das Kind möchte, darf Tomte ausziehen, mit dem Auszugs-Zettel." }
  ],

  /* Kleinigkeiten (Adventskalender-Schalter). Ehrlich: etwa 15–20 € pro Kind über 24 Tage, 3–4 Besorgungen, Rest aus Haus und Druckpaket.
     Regeln: bei mehreren Kindern kommen Gegenstände pro Kind; Puzzleteile liegen in einem Umschlag „für alle“. Unter 3 Jahren entfallen alle Kleinteile
     (Puzzleteile, Buntstift, Papierkugel), stattdessen Aufkleber oder Mandarine. Nie im Brief erwähnt, nie begründet, nie Belohnung und nie Entzug: Die Kleinigkeit liegt unabhängig von allem, was das Kind getan hat. */
  klein: {
    1:"Je ein Aufkleber am Brief (Sticker aus dem Druckpaket oder einer, der im Haus ist).",
    2:"Je ein Buntstift pro Kind (unter 3: Aufkleber).",
    3:"Ein Stoffrest oder Wollknäuel für Mimis Kissen, mit Schleife.",
    4:"Eine Mandarine mit aufgemaltem Gesicht (Rubi).",
    5:"Ein Teil aus einem 6-teiligen Puzzle (Druckpaket, auf festes Papier drucken; Teile an Tag 5, 9, 14, 18, 22, 24). Am Ende: Tomtes Vorgarten, ohne Tomte.",
    6:"Nikolaustag: Nüsse oder Schokolade sind heute ohnehin dran, Tomte bringt nur den Zapfen.",
    7:"Ein Holzstückchen mit Tomtes Zeichen (Kerbe oder Punkt), größer als ein Daumen.",
    8:"Je ein Paar bunte Socken.",
    9:"Ein Puzzleteil.",
    10:"Der Keks ist heute die Kleinigkeit.",
    11:"Ein Stück Fensterkreide, Mimis Farbe.",
    12:"Zwei Mandarinen pro Kind.",
    13:"Ein Stück Papierkette, genau 11 Zentimeter, Rubi hat nachgemessen (fertig geklebt, nicht lose).",
    14:"Ein Puzzleteil.",
    15:"Eine winzige Papierkugel aus dem Druckpaket für die Tanne, egal ob aus Papier oder Bausteinen.",
    16:"Ein Papierschneeball aus dem Druckpaket mit einem Rätsel innen.",
    17:"Ein Stück Butterbrotpapier mit Rubis Fußabdruck darauf (Druckpaket). Ersatzbatterien gehören zu den Eltern, nicht ins Tütchen.",
    18:"Ein Puzzleteil.",
    19:"Drei Wachsmaler in Farben, die zu Hause fehlen.",
    20:"Ein Mini-Mimi-Ausmalbild.",
    21:"Goldfolie oder Glitzerstift für den Stern.",
    22:"Ein Puzzleteil.",
    23:"Eine Tannennadel und eine Zapfenschuppe in einem Mini-Umschlag: Rubis Reiseproviant zum Behalten.",
    24:"Das letzte Puzzleteil liegt im Geschenk."
  },

  /* Tagsüber: Tomte bekommt mit, was passiert, und darf am Nachmittag Gutes tun. Nicht an Kalendertage gebunden. Eltern legen hin. */
  tagsueber: [
    { id:"tapfer", einzeln:true, titel:"Tapfer gewesen (Arzt, Zahnarzt, Impfung)", von:"tomte",
      brief:["Hallo {kinder},","als {ihr|du} heute nach Hause {kamt|kamst}, war das Haus anders. Rubi sagt, so riecht es, wenn jemand etwas Schweres hinter sich hat. Was es war, hat mir keiner gesagt, und ich frage nicht. Ich weiß nur: {Ihr seid|Du bist} wieder da, und {ihr habt|du hast} es gemacht. Ob dabei geweint wurde, viel oder wenig, gehört dazu.","Ich habe heute Nachmittag in der Werkstatt Pause gemacht, weil ich an {euch|dich} gedacht habe. Mimi hat geschlafen, das macht sie bei jedem Gedanken."],
      kurz:["Hallo {kinder},","{ihr habt|du hast} heute etwas Schweres gemacht. Weinen gehört dazu, viel oder wenig. Und jetzt {seid ihr|bist du} wieder da.","Mimi schläft vor Erleichterung."],
      tipp:"Am Nachmittag nach dem Termin an die Tür legen, nicht vorher versprechen. Tomte war nicht dabei und weiß nicht, was es war; er bemerkt nur, dass das Kind zurück ist. Kein Geschenk dazu, der Zettel ist die Sache. Nur, wenn der Termin wirklich stattgefunden hat." },
    { id:"traurig", einzeln:true, titel:"Ein trauriger Tag", von:"tomte",
      brief:["Hallo {kinder},","Mimi ist heute Nachmittag aufgewacht und hat gefragt, ob es {euch|dir} gut geht. Ich habe gesagt: Rubi meint, heute eher nicht. Da ist sie vor die Tür gegangen und hat sich an die Stelle gelegt, an der {ihr|du} vorbeikommt. Sie schläft da jetzt wieder. Aber sie liegt da für {euch|dich}.","Man muss nicht fröhlich sein, um einen Wichtel zu haben. Ich bleibe auch an traurigen Tagen. Besonders dann."],
      kurz:["Hallo {kinder},","Mimi ist heute aufgewacht und hat nach {euch|dir} gefragt. Jetzt liegt sie vor der Tür, für {euch|dich}.","Ich bleibe auch, wenn es ein trauriger Tag ist."],
      tipp:"Mimi an einen Ort legen, an dem das Kind sie sieht, ohne suchen zu müssen. Keine Aufgabe, keine Frage, kein „morgen wird besser“. Wenn das Kind den Grund nicht nennen will, fragt Tomte nicht nach." },
    { id:"einfachso", titel:"Einfach so (ohne Anlass)", von:"mimi",
      brief:["{kinder}.","Ich bin Mimi. Ich schreibe nur Zettel. Heute schreibe ich einen Brief. Das ist lang für mich.","Ich habe geträumt, dass {ihr|du} an mir vorbeigegangen {seid|bist} und mich angeguckt {habt|hast}. Dann bin ich aufgewacht. Dann wieder eingeschlafen. Guter Tag.","Mimi."],
      kurz:["{kinder}.","Ich bin Mimi. Ich schreibe nur Zettel. Heute einen Brief. Das ist lang.","Ich habe von {euch|dir} geträumt. Guter Tag. Mimi."],
      tipp:"Für einen Nachmittag, an dem nichts los ist. Mimis einziger ganzer Brief, deshalb nur einmal einsetzen. Kleine, krakelige Schrift, wenn ihr ihn von Hand abschreibt." }
  ],

  /* Tomte erzählt: Modellgeschichten zu Alltagsthemen. Tomte, Mimi oder Rubi erleben etwas (Wut, Streit, Neues probieren, Angst vor dem ersten Mal, Einschlafen).
     Sie bitten das Kind um nichts, fragen nichts nach, danken nicht unter Bedingung. Tomte erzieht nicht; wenn Eltern etwas wollen, sagen sie es selbst.
     Nie in der Woche eines Konflikts, nie mit Kleinigkeit oder Lob verknüpft. */
  hilfe: [
    { id:"schlafen", titel:"Einschlafen und im Bett bleiben", von:"tomte",
      brief:["Hallo {kinder},","nachts ist es still, da gelingt mir das Kleben am besten. Gestern war es laut in mir drin, da habe ich eine Seite verkehrt herum eingeklebt. Rubi hat es gemerkt, als er draufsaß.","Mimi hat mir verraten, wie sie so schnell einschläft: Sie denkt an eine einzige schöne Sache. Nur eine. Gestern war es ein Kissen, vorgestern auch. Ich habe es probiert, mit dem Baum, und war weg, bevor ich beim Stern war."],
      kurz:["Hallo {kinder},","Mimi schläft so schnell ein, weil sie an eine einzige schöne Sache denkt. Nur eine.","Ich habe es probiert, mit dem Baum. Ich war weg, bevor ich beim Stern war."],
      tipp:"Eine Geschichte, keine Aufgabe. Kein Bezug darauf, ob das Kind wach war, kein Nachfragen. Wer mag, fragt das Kind selbst beim Zubettgehen nach seiner einen Sache, ohne Tomte." },
    { id:"streit", titel:"Geschwisterstreit", von:"tomte",
      brief:["Hallo {kinder},","Mimi und Rubi haben sich heute gestritten, wer näher an meiner Tür schlafen darf. Rubi war laut, Mimi war still, und beide hatten recht. Am Ende hat Mimi gesagt: „Heute du, morgen ich.“ Rubi war so überrascht, dass er zugestimmt hat.","Ich habe mir das aufgeschrieben, weil ich es gut fand. Falls {ihr|du} es mal {braucht|brauchst}: Heute du, morgen ich. Es hat bei zwei Tieren funktioniert, die sich sonst nie einig sind."],
      kurz:["Hallo {kinder},","Mimi und Rubi haben gestritten. Dann hat Mimi gesagt: „Heute du, morgen ich.“ Das hat geklappt.","Falls {ihr|du} es mal {braucht|brauchst}."],
      tipp:"Tomte nennt nie den Streit der Kinder, nur den von Mimi und Rubi. Nicht am Tag des Streits legen, sondern einen Tag später, ohne Kommentar. Nur bei Geschwistern sinnvoll." },
    { id:"probieren", titel:"Neues Essen probieren", von:"tomte",
      brief:["Hallo {kinder},","Rubi frisst nur Beeren. Nur rote. Heute hat Mimi ihm im Schlaf ein Stück Apfel hingelegt, und er hat es aus Versehen probiert. Jetzt behauptet er, er habe Äpfel schon immer gemocht.","Mimi sagt, Probieren geht so: ein Krümel, nicht mehr. Wenn es schmeckt, gut. Wenn nicht, auch gut, dann weiß man es. Rubi sagt, er probiert nie wieder etwas. Morgen liegt wieder ein Apfel da. Mimi ist geduldig."],
      kurz:["Hallo {kinder},","Rubi frisst nur rote Beeren. Heute hat er aus Versehen Apfel probiert. Jetzt mag er Apfel.","Mimi sagt: Ein Krümel reicht. Rubi sagt: nie wieder. Mimi legt morgen wieder einen hin."],
      tipp:"Nur Geschichte, keine Bitte, kein Probierauftrag. Essdruck über eine geliebte Figur verstärkt Ablehnung. Wenn ihr wollt, legt ihr selbst ohne Kommentar einen Krümel auf den Teller, so wie Mimi." },
    { id:"wut", einzeln:true, titel:"Wut und Trotz", von:"tomte",
      brief:["Hallo {kinder},","heute war ich wütend. Richtig. Ein Brett ist dreimal zerbrochen, und ich habe den Hammer in die Ecke geworfen. Mimi hat nicht mal gezuckt.","Dann habe ich etwas gemacht, das ich von einem alten Wichtel gelernt habe. Manche Wichtel stampfen, manche gehen zu jemandem und lehnen sich an. Ich habe in meine Mütze gebrüllt. So laut ich konnte. Die Mütze hat alles geschluckt. Danach war das Brett immer noch kaputt, aber ich war wieder ich. Falls {ihr|du} mal eine Mütze {braucht|brauchst}: Rubi hat eine in {eurer|deiner} Größe besorgt, {fragt|frag} nicht woher. Sie liegt vor der Tür. Brüllmützen gibt es in jeder Größe."],
      kurz:["Hallo {kinder},","heute war ich wütend. Ein Brett ist kaputtgegangen.","Dann habe ich in meine Mütze gebrüllt. Das hilft. Vor der Tür liegt eine in {eurer|deiner} Größe."],
      tipp:"Wut wird nicht verboten, sie bekommt einen Ort. Eine Papiermütze aus dem Druckpaket oder eine alte Mütze hinlegen. Nie am Tag eines Wutanfalls, sondern an einem ruhigen Tag. Nie „Tomte hat dich gehört“. Die Mütze ist ein Angebot neben anderen (stampfen, anlehnen), keine Methode." },
    { id:"mut", einzeln:true, titel:"Mut (Kita, Schule, erstes Mal)", von:"rubi",
      brief:["{kinder}!","Morgen muss Tomte etwas, das er noch nie gemacht hat. Ich darf nicht sagen, was. Er hat die ganze Nacht nicht gehämmert, sondern ist nur hin und her gelaufen. Tausendmal. Hundertmal. Oft. Mimi hat ihm gesagt: „Mach es einmal, dann weißt du, wie es ist.“ Er hat genickt. Dann ist er wieder hin und her gelaufen.","Mimi sagt, morgen Abend weiß er, wie es war. Vorher weiß das keiner, auch kein Wichtel. Ich sitze so lange auf der Tür und zähle seine Schritte."],
      kurz:["{kinder}!","Tomte muss morgen etwas zum ersten Mal machen. Er hat Angst. Mimi sagt: einmal machen, dann weiß man es.","Mimi sagt: Morgen Abend weiß er, wie es war. Vorher weiß das keiner."],
      tipp:"Am Abend vor dem schwierigen Tag legen. Das Kind wird zum Vorbild, nicht zum Patienten. So hinlegen, dass er noch am selben Abend gelesen wird, nicht erst morgens. Am Abend danach ein Zettel von Tomte, unabhängig davon, wie es beim Kind lief: „Ich habe es gemacht. Es war komisch und dann vorbei. Mimi hatte recht.“ Nie die Sache des Kindes beim Namen nennen, wenn es selbst nicht darüber spricht, und nie fragen, wie es war." }
  ],

  /* Januar: Tomte darf bleiben, wird aber spürbar müde. Briefe wöchentlich, Aufwand sinkt mit jedem Brief. bis6 = Variante „bis Dreikönig“. */
  januar: [
    { datum:"01-01", titel:"Zurück aus dem Norden", von:"tomte",
      brief:["Hallo {kinder},","ich bin wieder da, wie versprochen. Rubi auch, er hat den Rückweg gefunden, sagt er. Das Treffen im Norden war laut, lang und voller Wichtel, die alle gleichzeitig erzählt haben. Alle haben gestaunt, und dann sind alle eingeschlafen, ich zuerst, mitten im Satz.","Jetzt bin ich müde. Richtig müde. Wichtel schlafen im Januar fast so viel wie Mimi. Darf ich noch ein bisschen bleiben, bevor ich nach Hause gehe? Ich werde nicht viel bauen. Ich werde vor allem schlafen. Aber ich bin da."],
      kurz:["Hallo {kinder},","ich bin zurück. Das Treffen im Norden war schön und laut. Jetzt bin ich sehr müde.","Darf ich noch ein bisschen bleiben? Ich schlafe viel. Aber ich bin da."],
      basis:{ t:"Die Rückkehr", x:"Brief vor die Tür, die Laterne wieder anmachen. Mimi liegt noch in ihrem Bett. Sonst nichts, Tomte ist müde.", m:"–", min:2, zeit:"am 31.12. nachmittags, bevor es rund geht" },
      tipp:"Nur, wenn ihr Tomte wirklich bis Januar behalten wollt. Ab jetzt gilt: etwa ein Brief pro Woche, keine Streiche. Das ist Absicht, Tomte wird spürbar träge. Sagt das Kind auf die Frage Nein: am nächsten Abend den Abschiedsabsatz vom 6. Januar geben, Laterne aus, Feder." },
    { datum:"01-06", titel:"Mimi zieht um", von:"tomte",
      brief:["Hallo {kinder},","heute ist Dreikönig, der Tag, an dem Wichtelpost langsamer wird. Mimi hat beschlossen, dass sie in eine Kiste umzieht. {Sucht|Such} ihr eine aus, mit Deckel und einem Luftloch, und {schaut|schau} rein, so oft {ihr|du} {wollt|willst}. Da ist es ruhig, sagt sie. Sie wird dort weiterschlafen, versprochen.","Ich habe heute Nacht nur eine Sache gemacht: Ich habe {eure|deine} Laterne geputzt. Danach habe ich mich zu Mimi gelegt. Zehn Minuten. Vielleicht zwei Stunden."],
      kurz:["Hallo {kinder},","Mimi zieht heute in eine Kiste um. {Sucht|Such} ihr eine aus. Da schläft sie weiter.","Ich habe nur die Laterne geputzt. Dann war ich müde."],
      briefEnde:"Und ich gehe heute Nacht auch, heim zu meinem Ofen, ausschlafen. Die Tür bleibt bei {euch|dir}. Im November ein JA, dann klopfe ich. Danke für den Winter. {Euer|Dein} Tomte",
      basis:{ t:"Mimi in die Kiste", x:"Das Kind sucht eine Kiste mit Deckel aus und legt Mimi mit ihrem Bett hinein. Die Tür bleibt hängen. Wer bei Dreikönig aufhört: Der Brief endet dann mit Tomtes Abschied; am Morgen danach Laterne aus, eine Feder auf dem Briefkasten, Tür am Wochenende gemeinsam abnehmen.", m:"Feder", min:3, zeit:"abends vorher" },
      tipp:"Natürlicher Ausstiegspunkt. Wer bis Ende Januar weitermacht, nimmt die nächsten drei Briefe." },
    { datum:"01-13", titel:"Mimi ist wach", von:"mimi",
      brief:["{kinder}.","Tomte schläft. Seit drei Tagen. Rubi redet. Ich bin wach. Das ist neu.","Es ist langweilig, wach zu sein. Draußen ist es so grau, dass Rubi sich selbst nicht sieht. Fast. {Malt|Mal} mir was. Dann habe ich was zum Angucken, bis ich wieder einschlafe.","Mimi."],
      kurz:["{kinder}.","Tomte schläft. Ich bin wach. Das ist neu und langweilig.","{Malt|Mal} mir was. Mimi."],
      basis:{ t:"Mimi wach", x:"Brief vor die Tür, Mimi einmal aus der Kiste holen und sitzend (Druckpaket: Mimi mit offenem Auge) auf den Briefkasten setzen. Wenn ein Bild kommt: an die Tür kleben, mit einem Zettel „Angeguckt. Jetzt schlafe ich. Mimi“.", m:"Klebefilm", min:2, zeit:"abends vorher" },
      tipp:"Ein ruhiger Brief für die graue Zeit. Kein Aufwand, kein Streich. Mimi ist zum ersten Mal richtig wach, das ist die kleine Überraschung des Januars." },
    { datum:"01-20", titel:"Heimweh nach dem Ofen", von:"tomte",
      brief:["Hallo {kinder},","heute ein kurzer Brief, Rubi hält mir die Laterne. Mimi schläft wieder, man hört es bis hierher.","Ich wollte nur sagen: Ich habe {euch|dich} nicht vergessen. Wichtel bekommen im Januar Heimweh nach ihrem eigenen Ofen, das ist bei allen so. Nächste Woche gehe ich heim, schlafe aus und esse Zimtbrei. Bis dahin sitze ich hinter der Tür und freue mich über das Licht, wenn abends die Laterne angeht."],
      kurz:["Hallo {kinder},","ein kurzer Brief. Wichtel bekommen im Januar Heimweh nach ihrem Ofen.","Nächste Woche gehe ich heim und esse Zimtbrei. Ich habe {euch|dich} nicht vergessen."],
      basis:{ t:"Kurzer Brief", x:"Brief vor die Tür, Laterne an. Die Zahlentafel bleibt auf 24 stehen.", m:"–", min:2, zeit:"abends vorher" },
      tipp:"Der Abschied wird angekündigt, damit er nächste Woche nicht überrascht." },
    { datum:"01-27", titel:"Bis zum Herbst", von:"tomte",
      brief:["Hallo {kinder},","heute Nacht gehe ich. Nicht weit, nur nach Hause zu meinem Ofen, wo Wichtel ausschlafen und Zimtbrei essen, bis es wieder früh dunkel wird. Rubi fliegt voraus. Diesmal hat er den Schrank nicht getroffen. Er hat trainiert.","Die Tür bleibt bei {euch|dir}. Mimi auch, in der Kiste. Wenn es im November wieder früh dunkel wird, {legt|leg} ein JA davor. Dann klopfe ich. Danke für den Winter. Es war ein guter. Ich merke mir den Ofen und {euch|dich}.","{Euer|Dein} Tomte"],
      kurz:["Hallo {kinder},","heute Nacht gehe ich nach Hause zu meinem Ofen und schlafe aus.","Die Tür bleibt. Mimi auch. Im November ein JA hinlegen, dann klopfe ich. Danke für den Winter.","{Euer|Dein} Tomte"],
      basis:{ t:"Der Abschied", x:"Brief vor die Tür, die Laterne ein letztes Mal an. Am nächsten Morgen: Laterne aus, auf dem Briefkasten eine Feder. Die Tür kommt am Wochenende in die Kiste, mit dem Kind zusammen.", m:"Feder", min:3, zeit:"abends vorher" },
      tipp:"Die Tür gemeinsam abnehmen, nicht heimlich. Das Kind darf sie in die Kiste legen. So endet es mit einer Handlung, nicht mit einer Leere." }
  ],

  /* Die Vorlesegeschichte. Beantwortet, was Briefe nicht können: Herkunft, Unsichtbarkeit, Mimi und Rubi.
     Eltern lesen sie am Abend vor dem Einzug vor (ganz) oder verteilt über die ersten Tage. Quelle: _quellen/geschichte/tomte-geschichte.md */
  geschichte: {
    titel: "Wie Tomte zu euch kam",
    unter: "Sieben kurze Kapitel. Am Abend vor dem Einzug vorlesen, oder eines pro Tag in der ersten Woche.",
    kapitel: [
      { n: 1, t: "Der Ort, an dem es Winter bleibt", wann: "Vorabend",
        text: ["Ganz weit oben im Norden, wo die Landkarten aufhören und nur noch Weiß ist, liegt ein Wald. Im Winter wird es dort nicht hell. Nicht ein bisschen dunkel, wie bei uns im Dezember um vier. Sondern gar nicht hell, wochenlang.",
               "In diesem Wald wohnen die Wichtel. Sie sind so groß wie eine Kinderhand und leben in Wänden: in Baumstämmen, in Felsspalten, in alten Scheunen. Wichtel mögen Wände. Eine Wand ist für einen Wichtel das, was für uns ein Haus ist.",
               "Und sie mögen Arbeit. Ein Wichtel, der nichts zu tun hat, wird traurig und fängt an, Dinge umzuräumen, die niemand umgeräumt haben wollte."] },
      { n: 2, t: "Die Wichtelreise", wann: "Vorabend",
        text: ["Jeder Wichtel muss einmal einen Winter bei Menschen verbringen. Das ist so üblich. Die alten Wichtel sagen: Man lernt das Helfen nicht zu Hause, man lernt es dort, wo einen keiner kennt.",
               "Also packen die jungen Wichtel im November ihre Taschen. Sie nehmen mit: einen Hammer, eine Säge, eine Decke, eine Mütze und ein leeres Buch. In das Buch kommt am Ende alles, was im Winter passiert ist.",
               "Dann suchen sie sich eine Familie. Nicht irgendeine. Eine, bei der noch Platz in einer Wand ist, und in der jemand wohnt, der an Wichtel denken könnte. Wichtel merken das. Wie, das verraten sie nicht."] },
      { n: 3, t: "Warum ihn niemand sehen darf", wann: "Vorabend oder Tag 1",
        text: ["Das ist das Wichtigste, und es ist keine Drohung, sondern einfach so:",
               "Ein Wichtel ist unsichtbar, solange ihn niemand gesehen hat. Seine ganze Kraft steckt darin. Er kann Dinge tragen, die zehnmal so schwer sind wie er. Er kann Geschenke kleiner machen. Er kann durch eine Wand gehen, in der eigentlich gar keine Tür ist.",
               "Sieht ihn ein Mensch, ist das alles weg. Dann ist er eine kleine Figur aus Holz, die irgendwo herumsteht. Schön anzusehen. Aber still.",
               "Deshalb macht ein Wichtel seine Arbeit nachts, wenn alle schlafen. Deshalb geht seine Tür nur von innen auf. Und deshalb schreibt er Briefe, statt zu reden: Eine Stimme verrät, wo jemand steht.",
               "Wenn ein Kind fragt, wie Tomte aussieht, antwortet er immer dasselbe: „Das weiß nur, wer mich nie gesehen hat.“"] },
      { n: 4, t: "Mimi", wann: "Tag 2 oder 3",
        text: ["Mimi ist eine Haselmaus. Haselmäuse schlafen den ganzen Winter, von Oktober bis April, zusammengerollt in einem Nest aus Gras.",
               "Mimi hat ihr Nest verpasst. Sie ist im Oktober eingeschlafen, auf einem Ast, mitten im Satz, und als sie aufwachte, war Schnee. Da saß sie nun.",
               "Tomte hat sie gefunden, als er losziehen wollte. Er hat sie in seine Mütze gesteckt und mitgenommen. Sie ist nie wieder richtig wach geworden, aber das macht nichts: Sie hat eine Posttasche, sie trägt Briefe, und sie schläft dabei ein. Fast immer. Manchmal kommt die Post deshalb später.",
               "Mimi erzählt gern von Tomte, aber sie verwechselt die Hälfte, weil sie die andere Hälfte verschlafen hat."] },
      { n: 5, t: "Rubi", wann: "Tag 3 oder 4",
        text: ["Rotkehlchen fliegen im Winter nicht weg. Sie bleiben da, auch wenn es kalt ist, und sitzen aufgeplustert auf Zäunen, damit sie dicker aussehen.",
               "Rubi hat Tomte gefunden, nicht umgekehrt. Er ist ihm hinterhergeflogen und hat geredet. Über den Schnee, über den Wind, über eine Katze, die er gesehen hatte und die angeblich so groß war wie ein Pferd.",
               "Tomte hat ihm irgendwann eine Aufgabe gegeben, damit das Reden wenigstens einen Sinn hat: Rubi fliegt nach draußen und bringt Nachrichten. Wie das Wetter ist. Was die Nachbarn machen. Ob der Schnee kommt.",
               "Er übertreibt bei jeder einzelnen Nachricht. Aber er kommt immer zurück."] },
      { n: 6, t: "Die Tür", wann: "Vorabend",
        text: ["Wenn ein Wichtel eine Familie gefunden hat, schickt er zuerst jemanden fragen. Bei Tomte ist das Rubi: Er legt einen Zettel hin und wartet auf eine Antwort.",
               "Kommt ein JA, dann passiert in der Nacht darauf etwas mit der Wand. Da, wo vorher nichts war, ist morgens eine kleine Tür. Von außen ist sie nur gemalt. Von innen geht sie auf.",
               "Dahinter wohnt Tomte den ganzen Dezember: in einer Stube mit Ofen und Schaukelstuhl, in einer Werkstatt mit Hobelspänen, und davor hat er einen winzigen Vorgarten.",
               "Kommt kein JA, geht er weiter und fragt woanders. Er ist dann nicht beleidigt. Wichtel sind nie beleidigt, dafür leben sie zu lange."] },
      { n: 7, t: "Was er den ganzen Dezember macht", wann: "Tag 1",
        text: ["Tomte hilft. Das ist seine Arbeit und er nimmt sie ernst.",
               "Nur: Er ist jung, er ist so groß wie eine Hand, und er kennt sich mit Menschendingen nicht aus. Also geht das Helfen oft schief. Er sortiert Socken nach Farbe, weil er glaubt, so gehöre sich das. Er will Frühstück machen und schafft es nicht bis zur obersten Schublade. Er baut eine Girlande, die elf Zentimeter lang wird.",
               "Jeden Morgen liegt ein Brief da, in dem er erzählt, was passiert ist. Und jede Nacht baut er die Zahl des Tages vor seine Tür, damit die Kinder wissen, wie lange er schon da ist.",
               "Und die ganze Zeit arbeitet er an etwas in seiner Werkstatt, von dem er nicht sagt, was es ist. Erst am 24. steht es vor der Tür.",
               "Dann muss er zurück in den Norden. Das ist traurig, aber so ist die Wichtelreise: Sie dauert einen Winter. Was bleibt, ist das Buch, das am Anfang leer war."] }
    ],
    eltern: "Die Geschichte erklärt alles, was Kinder fragen, ohne zu drohen: „Er verliert seine Kräfte“ ist eine Eigenschaft von Wichteln, keine Strafe für das Kind. Kapitel 3 ist der wichtigste, er nimmt dem Nichtöffnen der Tür die Spannung. Wer nicht vorlesen will, lässt sie weg; die Briefe tragen auch allein."
  },

  /* Zahlentafel: das tägliche Türchen. Jede Nacht steht die neue Zahl vor der Tür. Fünf Varianten, eine reicht. */
  tafel: [
    { id:"steine", t:"Klemmbausteine", x:"Grüne 8er-Platte, Ziffern aus hellen 1×2- und 1×3-Steinen (Muster 0–9 im Druckpaket). Wächst mit: ab Tag 13 Girlande, ab Tag 15 die Tanne daneben, ab Tag 21 der Stern.", min:1, wer:"Wer Klemmbausteine im Haus hat." },
    { id:"karten", t:"Zahlenkarten aus Papier", x:"24 gedruckte Karten im Tomte-Look, abends die neue in einen Papierständer vor der Tür stellen. Die alten kommen auf einen Stapel, der sichtbar wächst.", min:1, wer:"Der Standard ohne Material. Nur Drucker." },
    { id:"kreide", t:"Kleine Schiefertafel", x:"Eine Mini-Tafel (oder ein Stück schwarzer Karton) lehnt an der Wand. Tomte schreibt die Zahl mit Kreide, jede Nacht neu, in seiner krakeligen Schrift.", min:1, wer:"Schön für ältere Kinder: Man sieht die Handschrift, nicht nur die Zahl." },
    { id:"scheiben", t:"Holzscheiben oder Korken", x:"24 Baumscheiben, Korken oder Kieselsteine mit aufgemalten Zahlen in einem Säckchen. Jede Nacht legt Tomte die nächste vor die Tür, die anderen bleiben liegen und werden zu einem Weg.", min:1, wer:"Wer basteln mag, mit den Kindern im November vorbereiten." },
    { id:"fenster", t:"Fensterbild", x:"Mit Kreidestift an die Fensterscheibe neben der Tür, jede Nacht eine Zahl dazu, bis am 24. alle 24 dastehen. Nichts aufzubewahren, am Ende einmal abwischen.", min:1, wer:"Wer keinen Platz auf dem Boden hat." }
  ],

  /* Süßes: nur wenn Eltern es wollen. Grundeinstellung aus, dann bleibt Tomte ohne Süßigkeiten.
     Tomte erwähnt Süßes nie im Brief und knüpft es nie an Verhalten. Es liegt einfach da. */
  suess: {
    hinweis: "Mit dem Schalter bringt Tomte an diesen Tagen etwas Süßes mit. Es steht nie im Brief und ist nie an Verhalten geknüpft, es liegt einfach da. Wer den Schalter auslässt, bekommt die gleiche Geschichte ohne Süßigkeiten.",
    tage: {
      1:"Ein kleiner Schokoladentaler zur Begrüßung, in Tomtes Papier gewickelt.",
      4:"Ein Stück Lebkuchen, von dem eine winzige Ecke fehlt (Tomte hat probiert).",
      6:"Nikolaustag: Was ohnehin im Haus ist, liegt heute vor der Wichteltür statt im Schuh.",
      8:"Zwei Gummibärchen, Farbe sortiert. Tomte sortiert alles.",
      10:"Der Keks aus dem Brief, echt statt aus Papier.",
      12:"Zwei Stück von allem: eins für die Kinder, eins zum Verschenken am Überraschungs-Tag.",
      14:"Ein Mini-Schokoriegel, quer durchgebrochen, weil er nicht durch die Tür passte.",
      16:"Eine Mandarine mit einem Schokotaler obendrauf, als Schneemann gelegt.",
      18:"Ein Marshmallow in einem Papierbecher: Tomtes Vorstellung von einer Tasse Kakao.",
      20:"Schokolinsen, die eine Spur vom Briefkasten zu Mimis Versteck legen.",
      22:"Eine Handvoll Nüsse und Schokolade, Reiseproviant für den Norden, geteilt.",
      24:"Eine kleine Tafel Schokolade neben dem Geschenk, mit Tomtes Zeichen eingeritzt."
    },
    regeln: "Nie im Brief erwähnen. Nie als Belohnung oder Entzug. Nie an einem Tag, an dem auch ein Tagsüber- oder Erzähl-Brief liegt. Bei mehreren Kindern pro Kind dasselbe. Unter 3 Jahren nichts Hartes, keine Nüsse."
  },

  /* Die digitale Ebene. Grundsatz aus dem Kodex: Digitales ist erlaubt, wenn es sein Digitales verliert.
     Das Handy ist nie das Medium, sondern das Versteck: Es liegt neben der Tür, der Bildschirm zeigt kein Interface.
     status: "fertig" = liegt in public/medien, "skript" = Text steht, Produktion fehlt. */
  medien: [
    { id:"werkstatt", t:"Fenster in Tomtes Werkstatt", typ:"Bild mit Bewegung", status:"fertig", datei:"medien/werkstatt.html", wann:"Jederzeit, besonders Tag 15 bis 21",
      x:"Ein Blick durch das Fenster in seine Werkstatt, während er gerade draußen ist. Die Kerze flackert, der Hobel liegt da, Späne auf dem Boden, der Schaukelstuhl wippt noch nach. Kein Tomte. Es ändert sich langsam, man kann minutenlang zuschauen.",
      eltern:"Handy oder Tablet mit dunklem Hintergrund neben die Tür legen, Ton aus. Wirkt am besten abends. Beim ersten Mal nichts erklären, nur hinlegen." },
    { id:"suche", t:"Wo ist Mimi?", typ:"Suchbild", status:"fertig", datei:"medien/suche.html", wann:"Tag 20, oder an einem Regennachmittag",
      x:"Tomtes Stube als Wimmelbild. Mimi schläft irgendwo darin, jedes Mal woanders. Wer sie findet, darf sie antippen, dann dreht sie sich um und schläft weiter. Drei Runden, dann ist Schluss, keine Punkte, kein Gewinnen.",
      eltern:"Funktioniert ab 3. Kein Zeitdruck eingebaut, kein Ton. Wer schneller fertig ist, hat nichts gewonnen." },
    { id:"malbuch", t:"Tomtes Skizzenbuch", typ:"Malbuch zum Ausmalen", status:"fertig", datei:"medien/malbuch.html", wann:"Tag 3 (Mimi), Tag 11, Tag 19",
      x:"Halbfertige Zeichnungen aus Tomtes Buch: Mimi, Rubi, die Tür, der Vorgarten. Mit dem Finger oder der Maus ausmalen, Farben aus Tomtes Palette. Fertige Bilder kann man ausdrucken und vor die Tür legen, dann hängen sie am nächsten Tag in seiner Werkstatt.",
      eltern:"Ersetzt das gedruckte Ausmalbild, wenn kein Drucker da ist. Speichern geht als Bild über den Knopf unten." },
    { id:"hoer1", t:"Hörstück 1: Hinter der Tür", typ:"Audio, 50 Sekunden", status:"skript", wann:"Tag 14",
      x:"Mimi und Rubi streiten darüber, was Tomte baut. Tomte sagt dazwischen zweimal etwas, geflüstert, nicht ganz zu verstehen.",
      skript:["(Kratzen von Holz, weit weg. Dann näher: zwei Stimmen hinter einer Tür.)",
              "RUBI: Es ist ein Schiff! Ich habe es gesehen! Ein ganzes Schiff mit drei Masten!",
              "MIMI: (gähnt) Es ist ein Stuhl. Glaub ich.",
              "RUBI: Ein Stuhl! Mit drei Masten?",
              "MIMI: Ich habe nur den Anfang gesehen. Dann war ich weg.",
              "RUBI: Du bist immer weg.",
              "MIMI: Ich bin eine Maus.",
              "(Pause. Kratzen. Dann sehr leise, kaum zu verstehen:)",
              "TOMTE: (flüsternd) … seid mal still …",
              "RUBI: (flüsternd) Er hat gesagt, wir sollen still sein.",
              "MIMI: (schon im Einschlafen) … dann ist es ein Schiff …",
              "(Kratzen. Das Licht geht aus. Klick.)"],
      eltern:"Handy mit dunklem Bildschirm neben die Tür, leise, abends, ein Erwachsener dabei. Erst ab 5. Nicht bei Kindern, die abends ängstlich sind." },
    { id:"hoer2", t:"Hörstück 2: Rubi kommt zurück", typ:"Audio, 40 Sekunden", status:"skript", wann:"Tag 17",
      x:"Rubi ist durch den Schnee geflogen und berichtet, maßlos übertrieben. Mimi schläft und sagt einen Satz.",
      skript:["(Wind. Flügelschlag. Etwas landet.)",
              "RUBI: (außer Atem) Ich bin da! Ich bin DA! Der Schnee war so hoch wie ein Berg! Zwei Berge!",
              "(Stille.)",
              "RUBI: Hört mich jemand? Ich war WEG! Drei Tage!",
              "MIMI: (sehr verschlafen) Zwei Stunden.",
              "RUBI: Drei Tage, Mimi.",
              "MIMI: … zwei Stunden …",
              "(Pause.)",
              "RUBI: (leiser, fast zufrieden) Es war trotzdem ein Berg.",
              "(Es knistert. Ein Ofen. Dann still.)"],
      eltern:"Siehe oben. Gut direkt nach dem Brief von Tag 17." },
    { id:"hoer3", t:"Hörstück 3: Bis nächstes Jahr", typ:"Audio, 35 Sekunden", status:"skript", wann:"Tag 24, abends",
      x:"Der Abschied. Tomte sagt zum einzigen Mal mehr als drei Wörter, aber geflüstert und so nah am Mikrofon, dass man ihn eher spürt als hört. Danach wird es still.",
      skript:["(Ein Ofen knistert. Etwas wird zugeklappt: ein Buch.)",
              "TOMTE: (sehr leise, sehr nah) So. Fertig.",
              "(Pause.)",
              "TOMTE: Mimi bleibt hier. Pass auf sie auf, sie merkt es nicht, aber sie freut sich.",
              "(Schritte, ganz klein.)",
              "TOMTE: Es war ein guter Winter. Der beste Teil war der mit euch drin.",
              "(Eine Tür. Dann nichts mehr. Das Knistern wird leiser und hört auf.)"],
      eltern:"Nur, wenn das Kind den Abschied schon verstanden hat. Nicht morgens, sondern abends, nach dem Auspacken." },
    { id:"lied1", t:"Tomtes Arbeitslied", typ:"Lied, 40 Sekunden", status:"skript", wann:"Tag 19 oder jederzeit",
      x:"Was Tomte summt, während er hämmert. Einfache Melodie, drei Töne auf und ab, dazwischen Werkzeuggeräusche im Takt. Zum Mitsummen gedacht, nicht zum Mitsingen.",
      skript:["Ein Brett, ein Brett, ein krummes Brett,",
              "das macht nichts, das macht nichts.",
              "Ein Nagel rein, ein Nagel schief,",
              "das macht nichts, das macht nichts.",
              "(Hämmern, viermal, im Takt)",
              "Und wenn es morgen auseinanderfällt,",
              "dann bau ich es noch mal.",
              "Wichtel haben Zeit.",
              "Wichtel haben Zeit."],
      eltern:"Melodie bewusst einfach, damit Kinder sie nach zweimal Hören mitsummen. Kein Text zum Auswendiglernen." },
    { id:"lied2", t:"Mimis Schlaflied", typ:"Lied, 60 Sekunden", status:"skript", wann:"Abends, ab Tag 20",
      x:"Was Mimi im Schlaf murmelt. Sehr langsam, fast kein Takt, Summen zwischen den Zeilen. Zum Einschlafen, läuft aus statt zu enden.",
      skript:["Schlaf, kleiner Schnee,",
              "schlaf auf dem Dach.",
              "Keiner ist wach, keiner ist wach,",
              "nur der mit der Mütze,",
              "der arbeitet noch.",
              "(Summen)",
              "Schlaf, kleiner Wind,",
              "schlaf in der Wand.",
              "Morgen ist Post, morgen ist Post,",
              "wenn ich sie finde,",
              "wenn ich nicht schlaf.",
              "(Summen, wird leiser, hört einfach auf)"],
      eltern:"Darf jeden Abend laufen, auch außerhalb des Dezembers. Mimi bleibt ja." }
  ]
};
